// ---------------------------------------------------------------------------
// Tenant resolution: figure out which blog a request is for, from the Host.
// ---------------------------------------------------------------------------
async function resolveTenant(
  env: Bindings,
  hostHeader: string
): Promise<Tenant | null> {
  // Dev shortcut so you can browse at http://localhost:8787 without headers.
  if (env.DEV_TENANT) {
    return env.DB.prepare("SELECT * FROM tenants WHERE slug = ?")
      .bind(env.DEV_TENANT)
      .first<Tenant>();
  }

  const host = (hostHeader || "").split(":")[0].toLowerCase();
  if (!host) return null;

  // 1) A customer's own domain, connected + verified via Cloudflare for SaaS.
  const managed = await env.DB.prepare(
    `SELECT t.* FROM tenants t
       JOIN domains d ON d.tenant_id = t.id
      WHERE d.hostname = ? AND d.status = 'active'`
  )
    .bind(host)
    .first<Tenant>();
  if (managed) return managed;

  // 2) A custom domain set manually on the tenant row (simple single-domain case).
  const byDomain = await env.DB.prepare(
    "SELECT * FROM tenants WHERE custom_domain = ?"
  )
    .bind(host)
    .first<Tenant>();
  if (byDomain) return byDomain;

  // 3) A subdomain of the platform (<slug>.blognice.com).
  const root = env.ROOT_DOMAIN.toLowerCase();
  if (host.endsWith("." + root)) {
    const slug = host.slice(0, host.length - root.length - 1);
    if (slug && !slug.includes(".")) {
      return env.DB.prepare("SELECT * FROM tenants WHERE slug = ?")
        .bind(slug)
        .first<Tenant>();
    }
  }

  return null;
}

function originOf(c: { req: { url: string } }): string {
  const u = new URL(c.req.url);
  return `${u.protocol}//${u.host}`;
}

function customDomainRedirect(c: any, tenant: Tenant): Response | null {
  const location = customDomainRedirectUrl(c.req.url, tenant, c.env.ROOT_DOMAIN);
  return location ? Response.redirect(location, 308) : null;
}

// ---------------------------------------------------------------------------
// Edge caching. Reads are cached at the edge; writes purge the affected URLs.
// TTL is short so content stays fresh even if a purge is ever missed.
// ---------------------------------------------------------------------------
async function serveCached(
  c: any,
  build: () => Promise<Response>,
  varyConsent = false
): Promise<Response> {
  const cache = caches.default;
  // Bump this when public shell markup/CSS changes so old edge HTML cannot
  // hide newly shipped controls until the normal five-minute TTL expires.
  const cacheUrl = new URL(c.req.url);
  cacheUrl.searchParams.set("_bn_shell", CACHE_VERSION);
  // Keep public HTML in two consent cohorts, without fragmenting RSS/sitemap
  // caches by country.
  if (varyConsent) {
    const country = String(c.req.raw.cf?.country || "").trim().toUpperCase();
    cacheUrl.searchParams.set("_bn_consent", analyticsConsentRequired(country) ? "required" : "optional");
  }
  const key = new Request(cacheUrl.toString(), { method: "GET" });
  const hit = await cache.match(key);
  if (hit) return hit;

  const res = await build();
  if (res.status === 200) {
    res.headers.set("Cache-Control", "public, max-age=60, s-maxage=300");
    c.executionCtx.waitUntil(cache.put(key, res.clone()));
  }
  return res;
}

function cachePurgeVariants(url: string): string[] {
  return cacheVariants(url).flatMap((candidate) => {
    const parsed = new URL(candidate);
    if (!parsed.searchParams.has("_bn_shell")) return [candidate];
    return [candidate, ...["required", "optional"].map((cohort) => {
      const variant = new URL(parsed);
      variant.searchParams.set("_bn_consent", cohort);
      return variant.toString();
    })];
  });
}

async function purge(c: any, paths: string[]): Promise<void> {
  const cache = caches.default;
  const origin = originOf(c);
  await Promise.all(
    paths.flatMap((p) => cachePurgeVariants(origin + p).map((url) => cache.delete(new Request(url, { method: "GET" }))))
  );
}

// Purge pages served on a specific customer hostname (used when a domain
// activates, since those pages live under a different origin than the API).
async function purgeHost(hostname: string, paths: string[]): Promise<void> {
  const cache = caches.default;
  await Promise.all(
    paths.flatMap((p) => cachePurgeVariants(`https://${hostname}${p}`).map((url) =>
      cache.delete(new Request(url, { method: "GET" }))
    ))
  );
}

// Shared bearer-token check for the /api routes.
function authorized(c: any): boolean {
  return verifyPlatformBearer(c.req.header("authorization"), c.env.API_TOKEN);
}

// Basic hostname sanity check before we hand it to Cloudflare.
function validHostname(h: string, root: string): boolean {
  const host = h.toLowerCase();
  return (
    /^[a-z0-9.-]+$/.test(host) &&
    host.includes(".") &&
    !host.startsWith(".") &&
    !host.endsWith(".") &&
    host !== root &&
    !host.endsWith("." + root) // subdomains of your own zone don't need this flow
  );
}

// Turn a title into a URL-safe slug.
function slugify(s: string): string {
  return s
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

function randomSlugSuffix(): string {
  const alphabet = "abcdefghijklmnopqrstuvwxyz0123456789";
  const bytes = crypto.getRandomValues(new Uint8Array(5));
  let out = "";
  for (const b of bytes) out += alphabet[b % alphabet.length];
  return out;
}

function withSlugSuffix(base: string, maxLen = 80): string {
  const suffix = randomSlugSuffix();
  const trimmed = base.slice(0, maxLen - 6);
  return `${trimmed}-${suffix}`;
}

async function uniquePostSlug(pdb: any, tenantId: number, base: string, excludeId?: number, maxLen = 80): Promise<string> {
  let slug = base.slice(0, maxLen);
  for (let i = 0; i < 10; i++) {
    const clash = excludeId
      ? await pdb.prepare("SELECT 1 FROM posts WHERE tenant_id = ? AND slug = ? AND id <> ?").bind(tenantId, slug, excludeId).first()
      : await pdb.prepare("SELECT 1 FROM posts WHERE tenant_id = ? AND slug = ?").bind(tenantId, slug).first();
    if (!clash) return slug;
    slug = withSlugSuffix(base, maxLen);
  }
  return slug;
}

async function uniquePageSlug(pdb: any, tenantId: number, base: string, excludeId?: number, maxLen = 100): Promise<string> {
  let slug = base.slice(0, maxLen);
  for (let i = 0; i < 10; i++) {
    const clash = excludeId
      ? await pdb.prepare("SELECT 1 FROM pages WHERE tenant_id = ? AND slug = ? AND id != ?").bind(tenantId, slug, excludeId).first()
      : await pdb.prepare("SELECT 1 FROM pages WHERE tenant_id = ? AND slug = ?").bind(tenantId, slug).first();
    if (!clash) return slug;
    slug = withSlugSuffix(base, maxLen);
  }
  return slug;
}

// Subdomains we must never hand out as a tenant slug (they collide with our own
// hostnames/routes or are conventionally reserved).
const RESERVED_SLUGS = new Set([
  "www", "api", "admin", "signup", "login", "logout", "app", "apps", "mail",
  "email", "smtp", "imap", "pop", "ftp", "ns", "ns1", "ns2", "dns", "cname",
  "mx", "cdn", "static", "assets", "img", "images", "media", "files",
  "download", "downloads", "help", "support", "status", "dashboard", "account",
  "accounts", "billing", "blog", "blogs", "home", "root", "test", "dev",
  "staging", "demo", "cpanel", "webmail", "autoconfig", "autodiscover",
  "about", "contact", "terms", "privacy", "security", "abuse", "postmaster",
]);

// Validate a user-chosen blog address (the subdomain slug).
function validateSlug(s: string): string | null {
  if (!/^[a-z0-9-]+$/.test(s))
    return "Address may use only lowercase letters, numbers, and hyphens.";
  if (s.length < 3 || s.length > 40)
    return "Address must be between 3 and 40 characters.";
  if (s.startsWith("-") || s.endsWith("-") || s.includes("--"))
    return "Address can't start or end with a hyphen, or contain two in a row.";
  if (RESERVED_SLUGS.has(s)) return "That address is reserved.";
  return null;
}

async function ensureTenantHeaderLinkColumn(env: Bindings): Promise<void> {
  try {
    await env.DB.prepare("ALTER TABLE tenants ADD COLUMN header_link_url TEXT NOT NULL DEFAULT '/'").run();
  } catch {}
  try {
    await env.DB.prepare("ALTER TABLE tenants ADD COLUMN navigation_links_json TEXT NOT NULL DEFAULT '[]'").run();
  } catch {}
  try {
    await env.DB.prepare("ALTER TABLE tenants ADD COLUMN social_links_json TEXT NOT NULL DEFAULT '{}'").run();
  } catch {}
  try {
    await env.DB.prepare("ALTER TABLE tenants ADD COLUMN browser_push_enabled INTEGER NOT NULL DEFAULT 0").run();
  } catch {}
  try {
    await env.DB.prepare("ALTER TABLE tenants ADD COLUMN accent_color TEXT NOT NULL DEFAULT '#1a8917'").run();
  } catch {}
}

// All public hostnames a tenant is served on: its subdomain plus any active
// custom domains. Used to purge the right edge caches after an edit.
async function tenantHosts(
  env: Bindings,
  tenant: Tenant
): Promise<string[]> {
  const hosts = [`${tenant.slug}.${env.ROOT_DOMAIN}`];
  const { results } = await env.DB.prepare(
    "SELECT hostname FROM domains WHERE tenant_id = ? AND status = 'active'"
  )
    .bind(tenant.id)
    .all<{ hostname: string }>();
  for (const r of results) hosts.push(r.hostname);
  return hosts;
}

async function purgeTenant(
  env: Bindings,
  tenant: Tenant,
  paths: string[]
): Promise<void> {
  const cache = caches.default;
  const hosts = await tenantHosts(env, tenant);
  const jobs: Promise<boolean>[] = [];
  const purgePaths = Array.from(new Set([...paths, "/rss.xml"]));
  for (const host of hosts)
    for (const p of purgePaths)
      for (const url of cachePurgeVariants(`https://${host}${p}`))
        jobs.push(cache.delete(new Request(url, { method: "GET" })));
  await Promise.all(jobs);
}

// Purge the home page, sitemap, AND every post page for a blog. Used when
// something that appears on all posts changes (the byline: blog title, avatar).
async function purgeTenantEverywhere(
  env: Bindings,
  tenant: Tenant
): Promise<void> {
  const { results } = await tenantDb(env, tenant)
    .prepare("SELECT slug FROM posts WHERE tenant_id = ?")
    .bind(tenant.id)
    .all<{ slug: string }>();
  const paths = ["/", "/sitemap.xml", "/rss.xml", ...results.map((r) => "/" + r.slug)];
  await purgeTenant(env, tenant, paths);
}

async function purgeMasterSitemap(env: Bindings): Promise<void> {
  const wwwHost = `www.${env.ROOT_DOMAIN}`;
  const basePaths = ["/sitemap-index.xml"];
  try {
    const countRow = await env.DB.prepare("SELECT COUNT(*) as count FROM tenants WHERE slug <> 'www'").first<{ count: number }>();
    const total = countRow?.count ?? 0;
    const shardCount = Math.max(1, Math.ceil(total / MASTER_SITEMAP_PAGE_SIZE));
    for (let i = 1; i <= Math.min(shardCount, 100); i++) basePaths.push(`/sitemaps/blogs/${i}.xml`);
  } catch {}
  await purgeHost(wwwHost, basePaths);
}

// A blog's canonical public origin (its custom domain if set, else subdomain).
// Used for email links, which must point at the reader-facing host.
function publicOrigin(env: Bindings, tenant: Tenant): string {
  return `https://${tenant.custom_domain || `${tenant.slug}.${env.ROOT_DOMAIN}`}`;
}

function queueIndexNow(c: any, tenant: Tenant, paths: string[]): void {
  if (!c.env.INDEXNOW_QUEUE || !c.env.INDEXNOW_MASTER_SECRET) return;
  const origin = publicOrigin(c.env, tenant);
  const urls = Array.from(new Set(paths.map((path) => `${origin}${path.startsWith("/") ? path : `/${path}`}`)));
  c.executionCtx.waitUntil(c.env.INDEXNOW_QUEUE.send({ kind: "indexnow", urls }));
}

async function processIndexNow(env: Bindings, job: IndexNowMessage): Promise<void> {
  if (!env.INDEXNOW_MASTER_SECRET || !job.urls.length) return;
  const grouped = new Map<string, string[]>();
  for (const value of job.urls) {
    const url = new URL(value);
    const host = url.hostname.toLowerCase();
    const list = grouped.get(host) || [];
    list.push(url.toString());
    grouped.set(host, list);
  }
  for (const [host, urls] of grouped) {
    const key = await indexNowKey(env.INDEXNOW_MASTER_SECRET, host);
    const response = await fetch("https://api.indexnow.org/indexnow", {
      method: "POST",
      headers: { "content-type": "application/json; charset=utf-8" },
      body: JSON.stringify({ host, key, keyLocation: `https://${host}/.well-known/indexnow/${key}`, urlList: Array.from(new Set(urls)).slice(0, 10_000) }),
    });
    if (!response.ok && response.status !== 202) throw new Error(`IndexNow returned HTTP ${response.status}.`);
  }
}

// The parser-based renderer is the only renderer used by public pages and the
// live preview. The legacy implementation remains temporarily for comparison
// while deployments roll over, but is intentionally unreachable.
function renderMarkdown(md: string): string {
  return renderMarkdownSafe(md);
}

function subscriptionManageUrl(env: Bindings, token: string): string {
  return `https://www.${env.ROOT_DOMAIN}/manage-subscriptions/${encodeURIComponent(token)}`;
}

async function subscriptionManageToken(env: Bindings, email: string): Promise<string> {
  const existing = await env.DB.prepare("SELECT token FROM subscription_manage_tokens WHERE email = ?")
    .bind(email).first<{ token: string }>();
  if (existing) return existing.token;
  const token = crypto.randomUUID();
  try {
    await env.DB.prepare("INSERT INTO subscription_manage_tokens (email, token, created_at) VALUES (?, ?, ?)")
      .bind(email, token, Math.floor(Date.now() / 1000)).run();
    return token;
  } catch {
    const raced = await env.DB.prepare("SELECT token FROM subscription_manage_tokens WHERE email = ?")
      .bind(email).first<{ token: string }>();
    if (!raced) throw new Error("Unable to create subscription management token");
    return raced.token;
  }
}

async function tenantById(env: Bindings, id: number | string): Promise<Tenant | null> {
  return (await env.DB.prepare("SELECT * FROM tenants WHERE id = ?")
    .bind(id)
    .first()) as Tenant | null;
}

// Email every subscriber about a newly published post (no-op if email is off).
async function notifySubscribers(
  env: Bindings,
  tenant: Tenant,
  post: { slug: string; title: string }
): Promise<void> {
  if (!emailEnabled(env)) return;
  if (env.EMAIL_QUEUE) await env.EMAIL_QUEUE.send({ kind: "email-fanout", campaignId: crypto.randomUUID(), tenantId: tenant.id, postSlug: post.slug, postTitle: post.title, afterId: 0 } satisfies EmailFanoutMessage);
}

// Claim and queue the one notification allowed for a post. The conditional
// update makes editor/API races idempotent; failed queue submission releases
// the claim so a later publish attempt can retry.
async function queueSubscriberNotificationOnce(env: Bindings, tenant: Tenant, postId: number, post: { slug: string; title: string }): Promise<boolean> {
  if (!emailEnabled(env) || !env.EMAIL_QUEUE) return false;
  const result = await tenantDb(env, tenant).prepare(
    "UPDATE posts SET subscriber_notification_sent = 1 WHERE id = ? AND tenant_id = ? AND published = 1 AND subscriber_notification_sent = 0"
  ).bind(postId, tenant.id).run();
  if (result.meta.changes !== 1) return false;
  try {
    await notifySubscribers(env, tenant, post);
    return true;
  } catch (error) {
    await tenantDb(env, tenant).prepare("UPDATE posts SET subscriber_notification_sent = 0 WHERE id = ? AND tenant_id = ? AND subscriber_notification_sent = 1").bind(postId, tenant.id).run();
    throw error;
  }
}

async function pushEndpointHash(endpoint: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(endpoint));
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}

async function queueBrowserPushNotificationOnce(env: Bindings, tenant: Tenant, postId: number, post: { slug: string; title: string }): Promise<boolean> {
  if (!tenant.browser_push_enabled || !pushConfigured(env) || !env.PUSH_QUEUE) return false;
  const result = await tenantDb(env, tenant).prepare("UPDATE posts SET push_notification_sent = 1 WHERE id = ? AND tenant_id = ? AND published = 1 AND push_notification_sent = 0").bind(postId, tenant.id).run();
  if (result.meta.changes !== 1) return false;
  try {
    const source = await tenantDb(env, tenant).prepare("SELECT body_md FROM posts WHERE id = ? AND tenant_id = ? AND published = 1").bind(postId, tenant.id).first<{ body_md: string }>();
    const postExcerpt = source?.body_md.replace(/```[\s\S]*?```/g, " ").replace(/[#>*_`\[\]()>-]/g, " ").replace(/\s+/g, " ").trim().slice(0, 180) || "";
    const campaignId = crypto.randomUUID();
    const maxSubscription = await env.DB.prepare("SELECT COALESCE(MAX(id), 0) AS id FROM push_subscriptions WHERE tenant_id = ? AND topic = 'new-post'").bind(tenant.id).first<{ id: number }>();
    const now = Math.floor(Date.now() / 1000);
    await env.DB.prepare("INSERT INTO push_campaigns (campaign_id, tenant_id, topic, post_slug, post_title, post_excerpt, max_subscription_id, status, created_at) VALUES (?, ?, 'new-post', ?, ?, ?, ?, 'pending', ?)")
      .bind(campaignId, tenant.id, post.slug, post.title, postExcerpt, maxSubscription?.id || 0, now).run();
    await env.PUSH_QUEUE.send({ kind: "push-fanout", campaignId, tenantId: tenant.id, postSlug: post.slug, postTitle: post.title, postExcerpt, afterId: 0 } satisfies PushFanoutMessage);
    return true;
  } catch (error) {
    await tenantDb(env, tenant).prepare("UPDATE posts SET push_notification_sent = 0 WHERE id = ? AND tenant_id = ? AND push_notification_sent = 1").bind(postId, tenant.id).run();
    throw error;
  }
}

async function allowPushSubscription(env: Bindings, tenantId: number, ip: string): Promise<boolean> {
  if (!env.PUSH_IP_HMAC_SECRET) return false;
  const now = Math.floor(Date.now() / 1000);
  const windowStart = Math.floor(now / 3600) * 3600;
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(env.PUSH_IP_HMAC_SECRET), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const digest = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(ip.trim().slice(0, 128)));
  const ipHash = Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
  await env.DB.prepare("INSERT OR IGNORE INTO push_subscription_limits (tenant_id, ip_hash, window_start, attempts) VALUES (?, ?, ?, 0)").bind(tenantId, ipHash, windowStart).run();
  const row = await env.DB.prepare("UPDATE push_subscription_limits SET attempts = attempts + 1 WHERE tenant_id = ? AND ip_hash = ? AND window_start = ? RETURNING attempts").bind(tenantId, ipHash, windowStart).first<{ attempts: number }>();
  return !!row && row.attempts <= 20;
}

async function readBoundedJson(request: Request, limit = 8192): Promise<unknown | null> {
  const declared = Number(request.headers.get("content-length") || "0");
  if (declared > limit) return null;
  if (!(request.headers.get("content-type") || "").toLowerCase().startsWith("application/json")) return null;
  if (!request.body) return null;
  const reader = request.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  try {
    while (true) {
      const part = await reader.read();
      if (part.done) break;
      total += part.value.byteLength;
      if (total > limit) { await reader.cancel(); return null; }
      chunks.push(part.value);
    }
  } finally { reader.releaseLock(); }
  try {
    const bytes = new Uint8Array(total);
    let offset = 0;
    for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
    return JSON.parse(new TextDecoder().decode(bytes));
  } catch { return null; }
}

// ---------------------------------------------------------------------------
// Routes. Static paths are registered before the /:slug catch-all.
// ---------------------------------------------------------------------------

// Keep the apex domain as a canonical redirect to the public www homepage and
// admin host. DNS can resolve an apex, but only HTTP can preserve the path and
// tell browsers to use the canonical hostname.
app.use("*", async (c, next) => {
  const requestUrl = new URL(c.req.url);
  const host = requestUrl.hostname.toLowerCase();
  if (host === c.env.ROOT_DOMAIN.toLowerCase()) {
    const pathname = requestUrl.pathname;
    if (pathname === "/press" || pathname.startsWith("/press/") || pathname === "/press-kit" || pathname === "/press-kit.zip" || pathname === "/newsroom") {
      return next();
    }
    return c.redirect(
      `https://www.${c.env.ROOT_DOMAIN}${requestUrl.pathname}${requestUrl.search}`,
      301
    );
  }
  if (!host.startsWith("www.")) {
    const tenant = await resolveTenant(c.env, host);
    const redirect = tenant ? customDomainRedirect(c, tenant) : null;
    if (redirect) return redirect;
  }
  return next();
});

app.get("/sw.js", () => new Response(`self.addEventListener("push",function(event){var data={};try{data=event.data?event.data.json():{}}catch(_){}event.waitUntil(self.registration.showNotification(data.title||"New post",{body:data.body||"",icon:"/favicon.svg",badge:"/favicon.svg",tag:data.tag||"blognice-post",data:{url:data.url||"/"}}));});self.addEventListener("notificationclick",function(event){event.notification.close();var url=event.notification.data&&event.notification.data.url||"/";event.waitUntil(Promise.all([fetch("/_blognice/push/click",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({path:url}),keepalive:true}).catch(function(){}),clients.matchAll({type:"window",includeUncontrolled:true}).then(function(list){for(var i=0;i<list.length;i++){if("focus" in list[i]){list[i].navigate(url);return list[i].focus();}}return clients.openWindow(url);})]));});`, { headers: { "content-type": "application/javascript; charset=utf-8", "cache-control": "no-cache" } }));

app.get("/push/public-key", async (c) => {
  const tenant = await resolveTenant(c.env, new URL(c.req.url).hostname);
  if (!tenant || !tenant.browser_push_enabled || !pushConfigured(c.env)) return c.json({ error: "Browser push is not available." }, 404);
  return c.json({ publicKey: c.env.VAPID_PUBLIC_KEY });
});

app.post("/push/subscribe", async (c) => {
  const tenant = await resolveTenant(c.env, new URL(c.req.url).hostname);
  if (!tenant || !tenant.browser_push_enabled || !pushConfigured(c.env)) return c.json({ error: "Browser push is not available." }, 404);
  const origin = c.req.header("Origin");
  try { if (!origin || new URL(origin).origin !== new URL(c.req.url).origin) return c.json({ error: "Cross-origin requests are not allowed." }, 403); } catch { return c.json({ error: "Cross-origin requests are not allowed." }, 403); }
  if (!await allowPushSubscription(c.env, tenant.id, c.req.header("CF-Connecting-IP") || "unknown")) return c.json({ error: "Too many subscription attempts." }, 429);
  const value = await readBoundedJson(c.req.raw);
  if (!value || !await validBrowserPushSubscription(value)) return c.json({ error: "Invalid subscription." }, 400);
  const subscription = value as BrowserPushSubscription;
  const now = Math.floor(Date.now() / 1000);
  const endpointHash = await pushEndpointHash(subscription.endpoint);
  const saved = await c.env.DB.prepare(`INSERT INTO push_subscriptions (tenant_id, endpoint, endpoint_hash, topic, p256dh, auth, created_at, updated_at)
    SELECT ?, ?, ?, 'new-post', ?, ?, ?, ?
    WHERE EXISTS (SELECT 1 FROM push_subscriptions WHERE tenant_id = ? AND endpoint_hash = ? AND topic = 'new-post')
       OR (SELECT COUNT(*) FROM push_subscriptions WHERE tenant_id = ?) < 1000
    ON CONFLICT (tenant_id, endpoint_hash, topic) DO UPDATE SET endpoint = excluded.endpoint, p256dh = excluded.p256dh, auth = excluded.auth, updated_at = excluded.updated_at`)
    .bind(tenant.id, subscription.endpoint, endpointHash, subscription.keys.p256dh, subscription.keys.auth, now, now, tenant.id, endpointHash, tenant.id).run();
  if (saved.meta.changes !== 1) return c.json({ error: "This blog has reached its notification subscription limit." }, 429);
  try { recordCustomEvent(c.env, tenant.id, { name: "push_subscribed", path: "/", visitor: "", country: "", device: "", browser: "" }); } catch {}
  return c.json({ ok: true });
});

app.delete("/push/subscribe", async (c) => {
  const tenant = await resolveTenant(c.env, new URL(c.req.url).hostname);
  if (!tenant) return c.json({ error: "Not found." }, 404);
  const origin = c.req.header("Origin");
  try { if (!origin || new URL(origin).origin !== new URL(c.req.url).origin) return c.json({ error: "Cross-origin requests are not allowed." }, 403); } catch { return c.json({ error: "Cross-origin requests are not allowed." }, 403); }
  if (!await allowPushSubscription(c.env, tenant.id, c.req.header("CF-Connecting-IP") || "unknown")) return c.json({ error: "Too many subscription attempts." }, 429);
  const value = await readBoundedJson(c.req.raw);
  if (!value || !await validBrowserPushSubscription(value)) return c.json({ error: "Invalid subscription." }, 400);
  const endpointHash = await pushEndpointHash((value as BrowserPushSubscription).endpoint);
  await c.env.DB.prepare("DELETE FROM push_subscriptions WHERE tenant_id = ? AND endpoint_hash = ? AND topic = 'new-post'").bind(tenant.id, endpointHash).run();
  try { recordCustomEvent(c.env, tenant.id, { name: "push_unsubscribed", path: "/", visitor: "", country: "", device: "", browser: "" }); } catch {}
  return c.json({ ok: true });
});

app.get("/.well-known/indexnow/:key", async (c) => {
  const secret = c.env.INDEXNOW_MASTER_SECRET;
  const host = new URL(c.req.url).hostname.toLowerCase();
  const tenant = await resolveTenant(c.env, host);
  if (!secret || !tenant) return c.text("Not found", 404);
  const expected = await indexNowKey(secret, host);
  if (c.req.param("key") !== expected) return c.text("Not found", 404);
  return c.text(expected, { headers: { "cache-control": "public, max-age=86400, immutable" } });
});

