app.post("/admin/login", async (c) => {
  const form = await c.req.formData();
  const email = String(form.get("email") ?? "").trim().toLowerCase();
  const password = String(form.get("password") ?? "");
  const inviteToken = String(form.get("invite") ?? c.req.query("invite") ?? "").trim();

  const loginLimit = await checkLoginRateLimit(c, getClientIp(c), email);
  if (!loginLimit.allowed) {
    clearSessionCookie(c);
    const response = c.html(loginPage("Too many failed sign-in attempts. Please try again later."), 429);
    response.headers.set("Cache-Control", "no-store, max-age=0");
    response.headers.set("Retry-After", String(loginLimit.retryAfter || 900));
    return response;
  }

  const account = await c.env.DB.prepare(
    "SELECT id, pw_hash FROM accounts WHERE email = ?"
  )
    .bind(email)
    .first<{ id: number; pw_hash: string }>();

  const ok = account ? await verifyPassword(password, account.pw_hash) : false;
  if (!ok) {
    await recordFailedLogin(c, getClientIp(c), email);
    clearSessionCookie(c);
    let invite: { token: string; email: string; title: string; role: string } | undefined;
    if (inviteToken) {
      const h = await sha256hex(inviteToken);
      const now = Math.floor(Date.now() / 1000);
      const row = await c.env.DB.prepare("SELECT i.email, i.role, t.title FROM blog_invitations i JOIN tenants t ON t.id = i.tenant_id WHERE i.token_hash = ? AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > ?").bind(h, now).first<{ email: string; role: string; title: string }>();
      if (row) invite = { token: inviteToken, email: row.email, title: row.title, role: row.role };
    }
    const response = c.html(loginPage("Wrong email or password.", invite), 401);
    response.headers.set("Cache-Control", "no-store, max-age=0");
    return response;
  }

  await clearFailedLoginForEmail(c, email);

  const token = await createSession(c.env.DB, account!.id);
  try { const ip = getClientIp(c); const ua = String(c.req.header('User-Agent')||'').slice(0,300); await c.env.DB.prepare('UPDATE sessions SET ip=?, user_agent=?, created_via="login" WHERE token=?').bind(ip, ua, token).run(); try { await c.env.DB.prepare('INSERT INTO account_activity (id, account_id, kind, detail, ip, created_at) VALUES (?,?,?,?,?,?)').bind(crypto.randomUUID(), account!.id, 'login', 'login', ip, Math.floor(Date.now()/1000)).run(); } catch {} } catch {}
  clearSessionCookie(c);
  setSessionCookie(c, token);
  if (inviteToken) {
    const h = await sha256hex(inviteToken);
    const now = Math.floor(Date.now() / 1000);
    const invite = await c.env.DB.prepare("SELECT i.id, i.tenant_id, i.email, i.role, t.public_id FROM blog_invitations i JOIN tenants t ON t.id = i.tenant_id WHERE i.token_hash = ? AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > ?").bind(h, now).first<{ id: number; tenant_id: number; email: string; role: MembershipRole; public_id: string }>();
    if (invite) {
      if (invite.email === email) {
        await c.env.DB.prepare("INSERT INTO memberships (account_id, tenant_id, role, created_at) VALUES (?,?,?,?) ON CONFLICT(account_id,tenant_id) DO UPDATE SET role=excluded.role").bind(account!.id, invite.tenant_id, invite.role, now).run();
        await c.env.DB.prepare("UPDATE blog_invitations SET accepted_at = ? WHERE id = ?").bind(now, invite.id).run();
        return c.redirect(`/admin/b/${invite.public_id}`);
      }
    }
    return c.redirect(`/admin/invite/${encodeURIComponent(inviteToken)}`);
  }
  return c.redirect("/admin");
});

app.post("/admin/logout", async (c) => {
  const token = getSessionToken(c);
  if (token) await destroySession(c.env.DB, token);
  clearSessionCookie(c);
  const next = c.req.query("next");
  if (next && next.startsWith("/")) return c.redirect(next);
  return c.redirect("/admin/login");
});

// Account home: the list of this account's blogs.
app.get("/admin", async (c) => {
  const account = await currentAccount(c);
  if (!account) return c.redirect("/admin/login");
  if (isSuspended(account)) return suspendedResponse(c, account);
  if (!isEmailVerified(account) && emailEnabled(c.env)) return c.html(verificationPendingPage(account.email));
  const { results } = await c.env.DB.prepare(
    `SELECT t.public_id, t.slug, t.title, t.description, t.avatar_key, t.topics_json, m.role FROM tenants t
       JOIN memberships m ON m.tenant_id = t.id
      WHERE m.account_id = ? ORDER BY t.title`
  )
    .bind(account.id)
    .all<{ public_id: string; slug: string; title: string; description: string | null; avatar_key: string | null; topics_json: string | null; role: MembershipRole }>();
  const owned = results.filter((blog) => blog.role === "owner");
  const collaborations = results.filter((blog) => blog.role !== "owner");
  // With exactly one blog, jump straight in — unless the list was asked for
  // explicitly (the "Blogs" nav link), so that link always shows the picker.
  // Keep a new/incomplete blog on this page so the setup checklist is visible.
  const firstBlogNeedsSetup = owned.length === 1 && (
    !owned[0].description?.trim() || !owned[0].avatar_key || !owned[0].topics_json || owned[0].topics_json === "[]"
  );
  const forceList = c.req.query("list");
  if (!forceList && !firstBlogNeedsSetup && owned.length === 1 && collaborations.length === 0)
    return c.redirect(`/admin/b/${owned[0].public_id}`);
  return c.html(blogListPage(account, owned, collaborations, c.env.ROOT_DOMAIN));
});

