app.post("/admin/b/:blogId/pages/save", async (c) => {
  const ctx = await blogContext(c);
  if ("redirect" in ctx) return c.redirect(ctx.redirect);
  if ("suspended" in ctx) return suspendedResponse(c, ctx.account);
  const denied = requireBlogCapability(c, ctx, "posts.create");
  if (denied) return denied;
  const form = await c.req.formData();
  const idParam = c.req.query("id");
  const title = String(form.get("title") || "").trim().slice(0, 200);
  const body_md = String(form.get("body_md") || "");
  let slug = slugify(String(form.get("slug") || "")).slice(0, 100);
  if (!slug) slug = slugify(title).slice(0, 100);
  const published = form.get("published") ? 1 : 0;
  const showInNavigation = form.get("show_in_navigation") ? 1 : 0;
  const navigationLabel = String(form.get("navigation_label") || "").trim().slice(0, 40) || null;
  const navigationOrder = Math.max(0, Math.min(999, Number(form.get("navigation_order") || 0) || 0));
  const metaDescription = String(form.get("meta_description") || "").trim().slice(0, 300) || null;
  if (published && !can(ctx.role, "posts.publish")) return c.text("You do not have permission to publish pages.", 403);
  if (!title || !slug) return c.html(pageEditorPage(ctx.account, ctx.tenant, { id: idParam ? Number(idParam) : undefined, title, slug, body_md, published, show_in_navigation: showInNavigation, navigation_label: navigationLabel, navigation_order: navigationOrder, meta_description: metaDescription }, "A title is required (and it must produce a valid slug)."), 400);
  const now = Math.floor(Date.now() / 1000);
  const pdbPage = tenantDb(c.env, ctx.tenant);
  let previousSlugForPurge: string | null = null;
  if (idParam) {
    const prev = await pdbPage.prepare("SELECT slug, published_at FROM pages WHERE id = ? AND tenant_id = ?").bind(idParam, ctx.tenant.id).first<{ slug: string; published_at: number | null }>();
    if (!prev) return c.redirect(`/admin/b/${ctx.tenant.public_id}/pages`);
    previousSlugForPurge = prev.slug;
    if (slug !== prev.slug) {
      slug = await uniquePageSlug(pdbPage, ctx.tenant.id, slug, Number(idParam), 100);
    }
  } else {
    slug = await uniquePageSlug(pdbPage, ctx.tenant.id, slug, undefined, 100);
  }
  for (let attempts = 0; attempts < 6; attempts++) {
    try {
      if (idParam) {
        const previous = await pdbPage.prepare("SELECT slug, published_at FROM pages WHERE id = ? AND tenant_id = ?").bind(idParam, ctx.tenant.id).first<{ slug: string; published_at: number | null }>();
        if (!previous) return c.redirect(`/admin/b/${ctx.tenant.public_id}/pages`);
        await pdbPage.prepare("UPDATE pages SET slug = ?, title = ?, body_md = ?, published = ?, show_in_navigation = ?, navigation_label = ?, navigation_order = ?, meta_description = ?, updated_at = ?, published_at = ? WHERE id = ? AND tenant_id = ?")
          .bind(slug, title, body_md, published, showInNavigation, navigationLabel, navigationOrder, metaDescription, now, published ? (previous.published_at || now) : null, idParam, ctx.tenant.id).run();
        previousSlugForPurge = previous.slug;
        purgeTenant(c.env, ctx.tenant, ["/", `/pages/${previous.slug}`, `/pages/${slug}`, "/sitemap.xml"]);
      } else {
        await pdbPage.prepare("INSERT INTO pages (tenant_id, slug, title, body_md, published, show_in_navigation, navigation_label, navigation_order, meta_description, created_at, updated_at, published_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
          .bind(ctx.tenant.id, slug, title, body_md, published, showInNavigation, navigationLabel, navigationOrder, metaDescription, now, now, published ? now : null).run();
        purgeTenant(c.env, ctx.tenant, ["/", `/pages/${slug}`, "/sitemap.xml"]);
      }
      break;
    } catch (error) {
      const msg = String(error);
      if (/UNIQUE|unique|already/i.test(msg) && attempts < 5) {
        slug = withSlugSuffix(slug, 100);
        continue;
      }
      const message = msg.includes("UNIQUE") ? "That page slug is already in use." : "Could not save this page.";
      return c.html(pageEditorPage(ctx.account, ctx.tenant, { id: idParam ? Number(idParam) : undefined, title, slug, body_md, published, show_in_navigation: showInNavigation, navigation_label: navigationLabel, navigation_order: navigationOrder, meta_description: metaDescription }, message), 400);
    }
  }
  return c.redirect(`/admin/b/${ctx.tenant.public_id}/pages`);
});

app.post("/admin/b/:blogId/pages/delete/:id", async (c) => {
  const ctx = await blogContext(c);
  if ("redirect" in ctx) return c.redirect(ctx.redirect);
  if ("suspended" in ctx) return suspendedResponse(c, ctx.account);
  const denied = requireBlogCapability(c, ctx, "posts.delete");
  if (denied) return denied;
  const page = await tenantDb(c.env, ctx.tenant).prepare("SELECT slug FROM pages WHERE id = ? AND tenant_id = ?").bind(c.req.param("id"), ctx.tenant.id).first<{ slug: string }>();
  if (page) {
    await tenantDb(c.env, ctx.tenant).prepare("DELETE FROM pages WHERE id = ? AND tenant_id = ?").bind(c.req.param("id"), ctx.tenant.id).run();
    try {
      const navLinks = parseNavigationLinks(ctx.tenant as any);
      const href = `/pages/${page.slug}`;
      const filtered = navLinks.filter((l) => l.href !== href);
      if (filtered.length !== navLinks.length) {
        await c.env.DB.prepare("UPDATE tenants SET navigation_links_json = ? WHERE id = ?").bind(JSON.stringify(filtered), ctx.tenant.id).run();
        ctx.tenant = { ...ctx.tenant, navigation_links_json: JSON.stringify(filtered) } as any;
      }
    } catch {}
    await purgeTenant(c.env, ctx.tenant, ["/", `/pages/${page.slug}`, "/sitemap.xml"]);
  }
  return c.redirect(`/admin/b/${ctx.tenant.public_id}/pages`);
});

app.post("/admin/b/:blogId/navigation-links", async (c) => {
  const ctx = await blogContext(c);
  if ("redirect" in ctx) return c.redirect(ctx.redirect);
  if ("suspended" in ctx) return suspendedResponse(c, ctx.account);
  const denied = requireBlogCapability(c, ctx, "settings.manage");
  if (denied) return denied;
  const form = await c.req.formData();
  const label = String(form.get("label") || "").trim().slice(0, 40);
  const href = String(form.get("href") || "").trim().slice(0, 200);
  const order = Math.max(0, Math.min(999, Number(form.get("order") || 0) || 0));
  const { results: pages } = await tenantDb(c.env, ctx.tenant).prepare("SELECT * FROM pages WHERE tenant_id = ? ORDER BY navigation_order, updated_at DESC").bind(ctx.tenant.id).all<Page>();
  if (!label) return c.html(pageListPage(ctx.account, ctx.tenant, pages, c.env.ROOT_DOMAIN, { error: "A link label is required." }), 400);
  if (!href) return c.html(pageListPage(ctx.account, ctx.tenant, pages, c.env.ROOT_DOMAIN, { error: "A link target is required." }), 400);
  const isExternal = /^https:\/\//i.test(href);
  const isPath = /^\//.test(href);
  if (!isExternal && !isPath) return c.html(pageListPage(ctx.account, ctx.tenant, pages, c.env.ROOT_DOMAIN, { error: "Link target must be an absolute https URL or a path starting with /." }), 400);
  if (isExternal) { try { const u = new URL(href); if (u.protocol !== "https:") throw new Error(); } catch { return c.html(pageListPage(ctx.account, ctx.tenant, pages, c.env.ROOT_DOMAIN, { error: "External links must be valid https URLs." }), 400); } }
  if (isPath && /\s/.test(href)) return c.html(pageListPage(ctx.account, ctx.tenant, pages, c.env.ROOT_DOMAIN, { error: "Path links must not contain spaces." }), 400);
  const existing = parseNavigationLinks(ctx.tenant as any);
  if (existing.length >= 20) return c.html(pageListPage(ctx.account, ctx.tenant, pages, c.env.ROOT_DOMAIN, { error: "Use 20 navigation links or fewer." }), 400);
  const next = [...existing, { label, href, order }];
  await c.env.DB.prepare("UPDATE tenants SET navigation_links_json = ? WHERE id = ?").bind(JSON.stringify(next), ctx.tenant.id).run();
  queueBlogAudit(c, ctx.tenant.id, ctx.account.id, "navigation_link_added", href);
  c.executionCtx.waitUntil(purgeTenantEverywhere(c.env, { ...ctx.tenant, navigation_links_json: JSON.stringify(next) } as any).catch(() => {}));
  return c.redirect(`/admin/b/${ctx.tenant.public_id}/pages`);
});

app.post("/admin/b/:blogId/navigation-links/delete/:idx", async (c) => {
  const ctx = await blogContext(c);
  if ("redirect" in ctx) return c.redirect(ctx.redirect);
  if ("suspended" in ctx) return suspendedResponse(c, ctx.account);
  const denied = requireBlogCapability(c, ctx, "settings.manage");
  if (denied) return denied;
  const idx = Number(c.req.param("idx"));
  const existing = parseNavigationLinks(ctx.tenant as any);
  if (!Number.isInteger(idx) || idx < 0 || idx >= existing.length) return c.text("Invalid navigation link.", 400);
  const removed = existing[idx];
  const next = existing.filter((_, i) => i !== idx);
  await c.env.DB.prepare("UPDATE tenants SET navigation_links_json = ? WHERE id = ?").bind(JSON.stringify(next), ctx.tenant.id).run();
  queueBlogAudit(c, ctx.tenant.id, ctx.account.id, "navigation_link_removed", removed.href);
  c.executionCtx.waitUntil(purgeTenantEverywhere(c.env, { ...ctx.tenant, navigation_links_json: JSON.stringify(next) } as any).catch(() => {}));
  return c.redirect(`/admin/b/${ctx.tenant.public_id}/pages`);
});

// --- Collaborators --------------------------------------------------------
// Owners can invite an existing BlogNice account by email. The generated
// one-time link is shown to the owner so this works even when email delivery
// is not configured; the accepting account must have the invited email.
const COLLAB_ROLES = new Set<MembershipRole>(["editor", "author", "contributor"]);
function collaboratorPage(account: Account, tenant: Tenant, members: Array<{ account_id: number; email: string; role: string; display_name: string | null }>, invite?: string, error?: string): string {
  const rows = members.map((m) => `<tr><td>${esc(m.email)}</td><td>${esc(m.role)}</td><td><form method="post" style="display:flex;gap:.5rem;align-items:center"><input type="hidden" name="action" value="save-display-name"><input type="hidden" name="account_id" value="${m.account_id}"><input name="display_name" type="text" maxlength="120" value="${esc(m.display_name || "")}" placeholder="Public author name" aria-label="Public author name for ${esc(m.email)}"><button class="btn ghost" type="submit">Save</button></form></td></tr>`).join("");
  return shell("Collaborators", `<main class="page"><p class="breadcrumb"><a href="/admin/b/${esc(tenant.public_id)}">Posts</a> › Collaborators</p><h1>Collaborators</h1><p style="color:var(--muted);margin:-.8rem 0 1.6rem">Invite people to help write, edit, and publish posts according to their role.</p><div class="notice" style="margin-bottom:1.4rem"><strong>Author names</strong><br>Set a public author name for each person. This is what readers see next to <em>Author:</em> on published posts. It can differ from their login email and is specific to this blog; email addresses remain private.</div>${error ? `<div class="error">${esc(error)}</div>` : ""}<form method="post"><label for="collab-email">Email</label><input id="collab-email" type="email" name="email" required><label for="collab-role">Role</label><select id="collab-role" name="role"><option value="editor">Editor</option><option value="author">Author</option><option value="contributor">Contributor</option></select><div class="actions"><button class="btn" type="submit">Generate invite link</button></div></form>${invite ? `<div class="notice"><strong>Invite link generated</strong><br>Share this one-time link with the collaborator:<br><a href="${esc(invite)}">${esc(invite)}</a></div>` : ""}<h2>Current access</h2><table class="metrics"><thead><tr><th>Email</th><th>Role</th><th>Public author name</th></tr></thead><tbody>${rows}</tbody></table></main>`, account, tenant);
}

app.get("/admin/b/:blogId/authors", async (c) => {
  const ctx = await blogContext(c);
  if ("redirect" in ctx) return c.redirect(ctx.redirect);
  if ("suspended" in ctx) return suspendedResponse(c, ctx.account);
  if (!(await tenantHasPaidPlan(c.env, ctx.tenant.id))) return c.text("Collaborators are available on a paid plan.", 402);
  if (!can(ctx.role, "members.manage")) return c.text("You do not have permission to manage collaborators.", 403);
  const { results } = await c.env.DB.prepare(`SELECT m.account_id, a.email, m.role, m.display_name FROM memberships m JOIN accounts a ON a.id = m.account_id WHERE m.tenant_id = ? ORDER BY m.role, a.email`).bind(ctx.tenant.id).all<{ account_id: number; email: string; role: string; display_name: string | null }>();
  return c.html(collaboratorPage(ctx.account, ctx.tenant, results));
});

app.post("/admin/b/:blogId/authors", async (c) => {
  const ctx = await blogContext(c);
  if ("redirect" in ctx) return c.redirect(ctx.redirect);
  if ("suspended" in ctx) return suspendedResponse(c, ctx.account);
  if (!(await tenantHasPaidPlan(c.env, ctx.tenant.id))) return c.text("Collaborators are available on a paid plan.", 402);
  if (!can(ctx.role, "members.manage")) return c.text("You do not have permission to manage collaborators.", 403);
  const form = await c.req.formData();
  if (String(form.get("action") ?? "") === "save-display-name") {
    const accountId = Number(form.get("account_id") ?? 0);
    const displayName = String(form.get("display_name") ?? "").trim().slice(0, 120) || null;
    if (!Number.isInteger(accountId) || accountId < 1)
      return c.text("Invalid collaborator.", 400);
    await c.env.DB.prepare("UPDATE memberships SET display_name = ? WHERE tenant_id = ? AND account_id = ?")
      .bind(displayName, ctx.tenant.id, accountId).run();
    queueBlogAudit(c, ctx.tenant.id, ctx.account.id, "author_name_updated", String(accountId));
    return c.redirect(`/admin/b/${ctx.tenant.public_id}/authors`);
  }
  const email = String(form.get("email") ?? "").trim().toLowerCase();
  const role = String(form.get("role") ?? "") as MembershipRole;
  const { results } = await c.env.DB.prepare(`SELECT m.account_id, a.email, m.role, m.display_name FROM memberships m JOIN accounts a ON a.id = m.account_id WHERE m.tenant_id = ? ORDER BY m.role, a.email`).bind(ctx.tenant.id).all<{ account_id: number; email: string; role: string; display_name: string | null }>();
  if (!/^\S+@\S+\.\S+$/.test(email) || !COLLAB_ROLES.has(role)) return c.html(collaboratorPage(ctx.account, ctx.tenant, results, undefined, "Enter a valid email and role."), 400);
  const account = await c.env.DB.prepare("SELECT id FROM accounts WHERE email = ?").bind(email).first<{ id: number }>();
  if (account) {
    const existing = await c.env.DB.prepare("SELECT 1 FROM memberships WHERE tenant_id = ? AND account_id = ?").bind(ctx.tenant.id, account.id).first();
    if (existing) return c.html(collaboratorPage(ctx.account, ctx.tenant, results, undefined, "That account already has access to this blog."), 409);
  }
  const token = crypto.randomUUID() + crypto.randomUUID().replaceAll("-", "");
  const now = Math.floor(Date.now() / 1000);
  await c.env.DB.prepare("INSERT INTO blog_invitations (tenant_id,email,role,token_hash,invited_by,expires_at,created_at) VALUES (?,?,?,?,?,?,?)")
    .bind(ctx.tenant.id, email, role, await sha256hex(token), ctx.account.id, now + 7 * 86400, now).run();
  queueBlogAudit(c, ctx.tenant.id, ctx.account.id, "collaborator_invited", email);
  const origin = new URL(c.req.url).origin;
  return c.html(collaboratorPage(ctx.account, ctx.tenant, results, `${origin}/admin/invite/${token}`));
});

function invitePage(opts: { status: "valid" | "invalid" | "mismatch" | "accepted"; invite?: { token: string; email: string; role: string; title: string; expiresAt: number }; account?: Account | null; alreadyMember?: boolean; }): string {
  if (opts.status === "invalid") {
    return shell("Invitation", `<div class="page narrow"><h1>Invitation not found</h1><div class="error">This invitation is invalid, has expired, or was already used.</div><p style="color:var(--muted)">Ask the blog owner to send a fresh invite link.</p><p><a class="btn" href="/admin">Go to dashboard</a></p></div>`, opts.account ?? undefined);
  }
  const inv = opts.invite!;
  const expiresIn = Math.max(0, inv.expiresAt - Math.floor(Date.now() / 1000));
  const expiresLabel = expiresIn <= 0 ? "expired" : expiresIn < 3600 ? `${Math.ceil(expiresIn/60)} minutes` : expiresIn < 86400 ? `${Math.ceil(expiresIn/3600)} hours` : `${Math.ceil(expiresIn/86400)} days`;
  if (opts.status === "accepted" || opts.alreadyMember) {
    return shell("Invitation accepted", `<div class="page narrow"><h1>You're in</h1><div class="notice">You already have access to <strong>${esc(inv.title)}</strong> as <em>${esc(inv.role)}</em>.</div><p><a class="btn" href="/admin">Go to dashboard</a></p></div>`, opts.account ?? undefined);
  }
  if (!opts.account) {
    return shell("You're invited", `<div class="page narrow"><h1>You're invited to ${esc(inv.title)}</h1><div class="notice"><strong>${esc(inv.email)}</strong> has been invited to collaborate as <em>${esc(inv.role)}</em>.<br><span style="color:var(--muted);font-size:.9rem">Expires in ${esc(expiresLabel)} · One-time link</span></div><p style="color:var(--muted)">Sign in with <strong>${esc(inv.email)}</strong> or create an account with that email to accept.</p><div class="actions" style="display:flex;gap:.7rem;flex-wrap:wrap;margin:1.2rem 0"><a class="btn" href="/admin/login?invite=${esc(inv.token)}">Sign in to accept</a><a class="btn ghost" href="/signup?invite=${esc(inv.token)}">Create account</a></div><p style="color:var(--muted);font-size:.85rem">Link is for ${esc(inv.email)} only.</p></div>`);
  }
  if (opts.status === "mismatch") {
    return shell("Invitation", `<div class="page narrow"><h1>Switch account to accept</h1><div class="error">This invitation is for <strong>${esc(inv.email)}</strong>, but you're signed in as <strong>${esc(opts.account!.email)}</strong>.</div><p style="color:var(--muted)">Sign out and then sign in or create an account with the invited email.</p><div class="actions" style="display:flex;gap:.7rem;flex-wrap:wrap;margin:1.2rem 0"><form method="post" action="/admin/logout?next=${encodeURIComponent(`/admin/invite/${esc(inv.token)}`)}"><button class="btn" type="submit">Sign out</button></form><a class="btn ghost" href="/admin">Go to dashboard</a></div><p style="color:var(--muted);font-size:.85rem">Invitation: ${esc(inv.title)} · ${esc(inv.role)} · expires in ${esc(expiresLabel)}</p></div>`, opts.account);
  }
  return shell("Accept invitation", `<div class="page narrow"><h1>Accept invitation</h1><div class="notice">You've been invited to join <strong>${esc(inv.title)}</strong> as <em>${esc(inv.role)}</em>.<br><span style="color:var(--muted);font-size:.9rem">For ${esc(inv.email)} · Expires in ${esc(expiresLabel)}</span></div><form method="post" action="/admin/invite/${esc(inv.token)}" style="margin:1.2rem 0"><button class="btn" type="submit">Accept and go to blog</button></form><p style="color:var(--muted);font-size:.85rem">By accepting you'll be able to write, edit, and publish according to the <em>${esc(inv.role)}</em> role. If you didn't expect this, you can ignore it.</p></div>`, opts.account);
}

app.get("/admin/invite/:token", async (c) => {
  const token = c.req.param("token");
  const tokenHash = await sha256hex(token);
  const now = Math.floor(Date.now() / 1000);
  const account = await currentAccount(c);
  if (account && isSuspended(account)) return suspendedResponse(c, account);
  const invite = await c.env.DB.prepare("SELECT i.id, i.tenant_id, i.email, i.role, i.expires_at, i.accepted_at, i.revoked_at, t.title, t.public_id FROM blog_invitations i JOIN tenants t ON t.id = i.tenant_id WHERE i.token_hash = ?").bind(tokenHash).first<{ id: number; tenant_id: number; email: string; role: MembershipRole; expires_at: number; accepted_at: number | null; revoked_at: number | null; title: string; public_id: string }>();
  if (!invite || invite.accepted_at || invite.revoked_at || invite.expires_at <= now) {
    return c.html(invitePage({ status: "invalid", account }), 410);
  }
  const info = { token, email: invite.email, role: invite.role, title: invite.title, expiresAt: invite.expires_at };
  if (!account) {
    return c.html(invitePage({ status: "valid", invite: info, account: null }));
  }
  const member = await c.env.DB.prepare("SELECT 1 FROM memberships WHERE tenant_id = ? AND account_id = ?").bind(invite.tenant_id, account.id).first();
  if (member) {
    return c.html(invitePage({ status: "accepted", invite: info, account, alreadyMember: true }));
  }
  if (invite.email !== account.email) {
    return c.html(invitePage({ status: "mismatch", invite: info, account }), 403);
  }
  return c.html(invitePage({ status: "valid", invite: info, account }));
});

app.post("/admin/invite/:token", async (c) => {
  const token = c.req.param("token");
  const tokenHash = await sha256hex(token);
  const now = Math.floor(Date.now() / 1000);
  const account = await currentAccount(c);
  if (!account) return c.redirect(`/admin/login?invite=${encodeURIComponent(token)}`);
  if (isSuspended(account)) return suspendedResponse(c, account);
  const invite = await c.env.DB.prepare("SELECT i.id, i.tenant_id, i.email, i.role, i.expires_at, i.accepted_at, i.revoked_at, t.title, t.public_id FROM blog_invitations i JOIN tenants t ON t.id = i.tenant_id WHERE i.token_hash = ?").bind(tokenHash).first<{ id: number; tenant_id: number; email: string; role: MembershipRole; expires_at: number; accepted_at: number | null; revoked_at: number | null; title: string; public_id: string }>();
  if (!invite || invite.accepted_at || invite.revoked_at || invite.expires_at <= now) {
    return c.html(invitePage({ status: "invalid", account }), 410);
  }
  const info = { token, email: invite.email, role: invite.role, title: invite.title, expiresAt: invite.expires_at };
  const member = await c.env.DB.prepare("SELECT 1 FROM memberships WHERE tenant_id = ? AND account_id = ?").bind(invite.tenant_id, account.id).first();
  if (member) return c.redirect(`/admin/b/${invite.public_id}`);
  if (invite.email !== account.email) {
    return c.html(invitePage({ status: "mismatch", invite: info, account }), 403);
  }
  await c.env.DB.prepare("INSERT INTO memberships (account_id, tenant_id, role, created_at) VALUES (?,?,?,?) ON CONFLICT(account_id,tenant_id) DO UPDATE SET role=excluded.role").bind(account.id, invite.tenant_id, invite.role, now).run();
  await c.env.DB.prepare("UPDATE blog_invitations SET accepted_at = ? WHERE id = ?").bind(now, invite.id).run();
  return c.redirect(`/admin/b/${invite.public_id}`);
});

app.get("/admin/b/:blogId/metrics", async (c) => {
  const ctx = await blogContext(c);
  if ("redirect" in ctx) return c.redirect(ctx.redirect);
  if ("suspended" in ctx) return suspendedResponse(c, ctx.account);
  const requestedDays = Number(c.req.query("days") || "30");
  const days = [7, 30, 90].includes(requestedDays) ? requestedDays : 30;
  if (!metricsConfigured(c.env)) {
    return c.html(metricsPage(ctx.account, ctx.tenant, null, { days, configured: false, rootDomain: c.env.ROOT_DOMAIN }));
  }
  try {
    return c.html(
      metricsPage(ctx.account, ctx.tenant, await metricsReport(c.env, ctx.tenant.id, days), { rootDomain: c.env.ROOT_DOMAIN })
    );
  } catch (error) {
    console.error(JSON.stringify({
      message: "metrics report failed",
      tenantId: ctx.tenant.id,
      error: error instanceof Error ? error.message : String(error),
    }));
    return c.html(metricsPage(ctx.account, ctx.tenant, null, { days, rootDomain: c.env.ROOT_DOMAIN }), 502);
  }
});

