app.post("/admin/b/:blogId/settings", async (c) => {
  const ctx = await blogContext(c);
  if ("redirect" in ctx) return c.redirect(ctx.redirect);
  if ("suspended" in ctx) return suspendedResponse(c, ctx.account);
  const denied = requireBlogCapability(c, ctx, "settings.manage");
  if (denied) return denied;

  const origin = c.req.header("Origin");
  try {
    if (!origin || new URL(origin).origin !== new URL(c.req.url).origin) return c.text("Cross-origin requests are not allowed.", 403);
  } catch { return c.text("Cross-origin requests are not allowed.", 403); }

  const form = await c.req.formData();
  const slug = String(form.get("slug") ?? "").trim().toLowerCase();
  const title = String(form.get("title") ?? "").trim();
  const description = String(form.get("description") ?? "").trim();
  const browserPushEnabled = form.get("browser_push_enabled") === "1" ? 1 : 0;
  const footerName = String(form.get("footer_name") ?? "").trim().slice(0, 160);
  const accentColor = String(form.get("accent_color") ?? "").trim();
  const headerLinkRaw = String(form.get("header_link_url") ?? "/").trim();
  const headerLinkParsed = normalizeHeaderLink(headerLinkRaw);
  if (headerLinkParsed.error)
    return c.html(settingsPage(ctx.account, ctx.tenant, { error: headerLinkParsed.error }), 400);
  const headerLinkUrl = headerLinkParsed.url;
  const normalizedTopics = normalizeTopics(String(form.get("topics") ?? ""));
  const socialLinks: Record<string, string> = {};
  for (const key of ["x", "facebook", "instagram", "linkedin", "youtube", "tiktok", "bluesky", "mastodon", "bitchute", "telegram"]) {
    const value = String(form.get(`social_${key}`) ?? "").trim();
    if (!value) continue;
    if (value.length > 500) return c.html(settingsPage(ctx.account, ctx.tenant, { error: `${key} social link must be 500 characters or fewer.` }), 400);
    try {
      const url = new URL(value);
      if (url.protocol !== "https:") throw new Error("https required");
      socialLinks[key] = url.toString();
    } catch {
      return c.html(settingsPage(ctx.account, ctx.tenant, { error: `${key} social link must be a valid HTTPS URL.` }), 400);
    }
  }
  const slugError = validateSlug(slug);
  if (slugError)
    return c.html(settingsPage(ctx.account, ctx.tenant, { error: slugError }), 400);
  if (slug !== ctx.tenant.slug) {
    const taken = await c.env.DB.prepare("SELECT 1 FROM tenants WHERE slug = ? UNION SELECT 1 FROM tenant_slug_aliases WHERE old_slug = ?")
      .bind(slug, slug).first();
    if (taken) return c.html(settingsPage(ctx.account, ctx.tenant, { error: "That blog address is already in use." }), 409);
  }
  if (!title)
    return c.html(settingsPage(ctx.account, ctx.tenant, { error: "A blog title is required." }), 400);
  if (normalizedTopics.error)
    return c.html(settingsPage(ctx.account, ctx.tenant, { error: normalizedTopics.error }), 400);
  if (!/^#[0-9a-f]{6}$/i.test(accentColor))
    return c.html(settingsPage(ctx.account, ctx.tenant, { error: "Brand colour must be a six-digit hex value, such as #1a8917." }), 400);

  const now = Math.floor(Date.now() / 1000);
  if (slug !== ctx.tenant.slug) {
    await c.env.DB.prepare("INSERT INTO tenant_slug_aliases (old_slug, tenant_id, created_at) VALUES (?, ?, ?)")
      .bind(ctx.tenant.slug, ctx.tenant.id, now).run();
  }
  await ensureTenantHeaderLinkColumn(c.env);
  await c.env.DB.prepare("UPDATE tenants SET slug = ?, title = ?, description = ?, footer_name = ?, accent_color = ?, topics_json = ?, social_links_json = ?, browser_push_enabled = ?, header_link_url = ? WHERE id = ?")
    .bind(slug, title, description, footerName, accentColor.toLowerCase(), JSON.stringify(normalizedTopics.topics), JSON.stringify(socialLinks), browserPushEnabled, headerLinkUrl, ctx.tenant.id)
    .run();
  queueBlogAudit(c, ctx.tenant.id, ctx.account.id, "blog_settings_updated", "settings");

  c.executionCtx.waitUntil(purgeTenantEverywhere(c.env, ctx.tenant));
  const updated = { ...ctx.tenant, slug, title, description, footer_name: footerName, accent_color: accentColor.toLowerCase(), topics_json: JSON.stringify(normalizedTopics.topics), social_links_json: JSON.stringify(socialLinks), browser_push_enabled: browserPushEnabled, header_link_url: headerLinkUrl };
  return c.html(settingsPage(ctx.account, updated, { notice: "Saved." }));
});

app.post("/admin/b/:blogId/push-campaigns/:campaignId/replay", async (c) => {
  const ctx = await blogContext(c);
  if ("redirect" in ctx) return c.redirect(ctx.redirect);
  if ("suspended" in ctx) return suspendedResponse(c, ctx.account);
  const denied = requireBlogCapability(c, ctx, "settings.manage");
  if (denied) return denied;
  if (!ctx.tenant.browser_push_enabled || !pushConfigured(c.env) || !c.env.PUSH_QUEUE) return c.json({ error: "Browser push is not enabled or configured." }, 409);
  const origin = c.req.header("Origin");
  try {
    if (!origin || new URL(origin).origin !== new URL(c.req.url).origin) return c.json({ error: "Cross-origin requests are not allowed." }, 403);
  } catch { return c.json({ error: "Cross-origin requests are not allowed." }, 403); }
  const campaign = await c.env.DB.prepare("SELECT campaign_id, tenant_id, post_slug, post_title, post_excerpt FROM push_campaigns WHERE campaign_id = ? AND tenant_id = ?")
    .bind(c.req.param("campaignId"), ctx.tenant.id).first<{ campaign_id: string; tenant_id: number; post_slug: string; post_title: string; post_excerpt: string }>();
  if (!campaign) return c.json({ error: "Campaign not found." }, 404);
  const replayed = await c.env.DB.prepare("UPDATE push_campaigns SET status = 'pending', completed_at = NULL WHERE campaign_id = ? AND tenant_id = ? AND status IN ('failed', 'retry-exhausted')")
    .bind(campaign.campaign_id, ctx.tenant.id).run();
  if (!replayed.meta.changes) return c.json({ ok: true, queued: false });
  await c.env.DB.prepare("UPDATE push_deliveries SET status = 'pending', claimed_at = NULL WHERE campaign_id = ? AND status != 'sent' AND EXISTS (SELECT 1 FROM push_campaigns WHERE campaign_id = ? AND tenant_id = ?)")
    .bind(campaign.campaign_id, campaign.campaign_id, ctx.tenant.id).run();
  try {
    await c.env.PUSH_QUEUE.send({ kind: "push-fanout", campaignId: campaign.campaign_id, tenantId: ctx.tenant.id, postSlug: campaign.post_slug, postTitle: campaign.post_title, postExcerpt: campaign.post_excerpt, afterId: 0 } satisfies PushFanoutMessage);
  } catch (error) {
    await c.env.DB.prepare("UPDATE push_campaigns SET status = 'failed', completed_at = NULL WHERE campaign_id = ? AND tenant_id = ? AND status = 'pending'")
      .bind(campaign.campaign_id, ctx.tenant.id).run();
    throw error;
  }
  queueBlogAudit(c, ctx.tenant.id, ctx.account.id, "push_campaign_replayed", campaign.campaign_id);
  return c.json({ ok: true });
});

// Avatar upload → R2; stores the key on the blog. Client pre-shrinks it.
app.post("/admin/b/:blogId/avatar", async (c) => {
  const ctx = await blogContext(c);
  if ("redirect" in ctx) return c.json({ error: "unauthorized" }, 401);
  if ("suspended" in ctx) return c.json({ error: "Your account is currently suspended and you should contact support." }, 403);
  if (!can(ctx.role, "settings.manage")) return c.json({ error: "forbidden" }, 403);

  const form = await c.req.formData();
  const file = form.get("file");
  if (!(file instanceof File)) return c.json({ error: "no file" }, 400);
  if (!ALLOWED_IMAGE.has(file.type) || (await detectedImageType(file)) !== file.type)
    return c.json({ error: "unsupported image type" }, 400);
  if (file.size > MAX_UPLOAD) return c.json({ error: "image too large" }, 413);

  const rand = crypto.randomUUID().slice(0, 8);
  const key = `${ctx.tenant.id}/avatar-${rand}.${EXT[file.type]}`;
  await c.env.MEDIA.put(key, await file.arrayBuffer(), {
    httpMetadata: {
      contentType: file.type,
      cacheControl: "public, max-age=31536000, immutable",
    },
  });

  // Delete the previous avatar object, if any, then point the blog at the new one.
  if (ctx.tenant.avatar_key)
    c.executionCtx.waitUntil(c.env.MEDIA.delete(ctx.tenant.avatar_key));
  await c.env.DB.prepare("UPDATE tenants SET avatar_key = ? WHERE id = ?")
    .bind(key, ctx.tenant.id)
    .run();

  c.executionCtx.waitUntil(purgeTenantEverywhere(c.env, ctx.tenant));
  return c.json({ url: `/media/${key}` });
});

