// ---------------------------------------------------------------------------
// Public self-service signup: visitor -> their own blog, logged in.
// ---------------------------------------------------------------------------
function getClientIp(c: any): string {
  const cfIp = String(c.req.header("cf-connecting-ip")||"").trim();
  if (cfIp) return cfIp.slice(0,64);
  return "unknown";
}
async function checkSignupRateLimit(c: any, ip: string, email: string): Promise<{ allowed: boolean; retryAfter?: number }> {
  const now = Math.floor(Date.now() / 1000);
  const windowSec = 3600;
  const windowStart = now - (now % windowSec);
  // const maxPerIp = 5
  // const maxPerEmail = 3
  let maxPerIp = 5;
  let maxPerEmail = 3;
  try {
    const ipOverride = await c.env.DB.prepare("SELECT max_signups_per_hour FROM staff_rate_limit_overrides WHERE account_id IN (SELECT id FROM accounts WHERE signup_ip=? LIMIT 1)").bind(ip).first() as any;
    if (ipOverride?.max_signups_per_hour) maxPerIp = Number(ipOverride.max_signups_per_hour);
  } catch {}
  try {
    const emailOverride = await c.env.DB.prepare("SELECT max_signups_per_hour, max_logins_per_hour FROM staff_rate_limit_overrides WHERE account_id = (SELECT id FROM accounts WHERE email=? LIMIT 1)").bind(email.toLowerCase()).first() as any;
    if (emailOverride?.max_signups_per_hour) maxPerEmail = Number(emailOverride.max_signups_per_hour);
    if (emailOverride?.max_logins_per_hour) maxPerIp = Math.min(maxPerIp, Number(emailOverride.max_logins_per_hour));
  } catch {}
  try {
    const ipRow = await (c.env.DB.prepare("SELECT count, window_start FROM signup_rate_limits WHERE ip = ?").bind(`ip:${ip}`).first() as Promise<{ count: number; window_start: number } | null>).catch(()=>null);
    if (ipRow) {
      if (ipRow.window_start === windowStart && ipRow.count >= maxPerIp) return { allowed: false, retryAfter: windowStart + windowSec - now };
      if (ipRow.window_start !== windowStart) await c.env.DB.prepare("UPDATE signup_rate_limits SET window_start=?, count=1 WHERE ip=?").bind(windowStart, `ip:${ip}`).run().catch(()=>{});
      else await c.env.DB.prepare("UPDATE signup_rate_limits SET count=count+1 WHERE ip=?").bind(`ip:${ip}`).run().catch(()=>{});
    } else {
      await c.env.DB.prepare("INSERT INTO signup_rate_limits (ip, window_start, count) VALUES (?, ?, 1)").bind(`ip:${ip}`, windowStart, 1).run().catch(()=>{});
    }
    const emailKey = `email:${email.toLowerCase()}`;
    const emRow = await (c.env.DB.prepare("SELECT count, window_start FROM signup_rate_limits WHERE ip = ?").bind(emailKey).first() as Promise<{ count: number; window_start: number } | null>).catch(()=>null);
    if (emRow) {
      if (emRow.window_start === windowStart && emRow.count >= maxPerEmail) return { allowed: false, retryAfter: windowStart + windowSec - now };
      if (emRow.window_start !== windowStart) await c.env.DB.prepare("UPDATE signup_rate_limits SET window_start=?, count=1 WHERE ip=?").bind(windowStart, emailKey).run().catch(()=>{});
      else await c.env.DB.prepare("UPDATE signup_rate_limits SET count=count+1 WHERE ip=?").bind(emailKey).run().catch(()=>{});
    } else {
      await c.env.DB.prepare("INSERT INTO signup_rate_limits (ip, window_start, count) VALUES (?, ?, 1)").bind(emailKey, windowStart, 1).run().catch(()=>{});
    }
  } catch {}
  try { await c.env.DB.prepare("DELETE FROM signup_rate_limits WHERE window_start < ?").bind(now - 86400).run(); } catch {}
  return { allowed: true };
}
async function createEmailVerification(c: any, accountId: number, email: string, blogTitle?: string): Promise<string> {
  if (!emailEnabled(c.env)) {
    const now2 = Math.floor(Date.now()/1000);
    await c.env.DB.prepare("UPDATE accounts SET email_verified=1, email_verified_at=? WHERE id=?").bind(now2, accountId).run().catch(()=>{});
    return "";
  }
  const token = generateResetToken(32);
  const hash = await sha256hex(token);
  const now = Math.floor(Date.now() / 1000);
  const expires = now + 86400;
  await c.env.DB.prepare("INSERT OR REPLACE INTO account_email_verifications (account_id, token_hash, expires_at, created_at) VALUES (?, ?, ?, ?)").bind(accountId, hash, expires, now).run();
  const origin = new URL(c.req.url).origin;
  const verifyUrl = `${origin}/verify-email?token=${encodeURIComponent(token)}`;
  c.executionCtx.waitUntil(sendEmail(c.env, { to: email, ...emailVerificationEmail({ verifyUrl, blogTitle }) }));
  return token;
}
function verificationPendingPage(email: string, resend?: boolean): string {
  return shell(`Verify email — blognice`, `<div class="page narrow"><h1>Check your email</h1><p>We sent a verification link to <strong>${esc(email)}</strong>. Click the link to activate your blog (expires in 24 hours).</p>${resend?`<p style="color:#1a8917">New link sent — check your inbox.</p>`:""}<form method="post" action="/verify-email/resend" style="margin:1rem 0"><input type="hidden" name="email" value="${esc(email)}"><button class="btn" type="submit">Resend link</button></form><p style="color:var(--muted);font-size:.9rem">Didn't get it? Check spam, or try resending. You can also <a href="/admin/login">sign in</a> after verifying.</p></div>`);
}
function verificationResultPage(ok: boolean, msg?: string): string {
  return ok
    ? shell(`Email verified — blognice`, `<div class="page narrow"><h1>Email verified</h1><p>Your email is confirmed. Your blog is now active.</p><p><a class="btn" href="/admin">Go to dashboard →</a></p></div>`)
    : shell(`Verification failed — blognice`, `<div class="page narrow"><h1>Link invalid or expired</h1><p>${esc(msg||"This verification link is invalid or has expired.")}</p><p><a href="/verify-email/resend">Resend link</a> · <a href="/admin/login">Sign in</a></p></div>`);
}
async function recordAffiliateSignup(c: any, accountId: number): Promise<void> {
  if (analyticsConsentRequired(c.req.raw.cf?.country)) return;
  const attribution = await c.env.DB.prepare(
    `SELECT attribution.affiliate_id, attribution.source, attribution.policy_version,
            assignment.experiment_key, assignment.variant
       FROM affiliate_attributions AS attribution
       LEFT JOIN funnel_experiment_assignments AS assignment
         ON assignment.account_id = attribution.referred_account_id AND assignment.excluded_at IS NULL
      WHERE attribution.referred_account_id = ?`,
  ).bind(accountId).first() as { affiliate_id: number; source: "link" | "code"; policy_version: string; experiment_key: string | null; variant: "control" | "focused" | null } | null;
  if (attribution) recordAffiliateFunnelEvent(c.env, attribution.affiliate_id, {
    name: "affiliate_signup",
    source: attribution.source,
    policyVersion: attribution.policy_version,
    experimentKey: attribution.experiment_key || undefined,
    variant: attribution.variant || undefined,
  });
}
async function recordExperimentCheckoutStart(c: any, accountId: number): Promise<void> {
  if (analyticsConsentRequired(c.req.raw.cf?.country)) return;
  const row = await c.env.DB.prepare(
    `SELECT affiliate_id, policy_version, experiment_key, variant
       FROM funnel_experiment_assignments WHERE account_id = ? AND excluded_at IS NULL`,
  ).bind(accountId).first() as { affiliate_id: number; policy_version: string; experiment_key: string; variant: "control" | "focused" } | null;
  if (row) recordAffiliateFunnelEvent(c.env, row.affiliate_id, {
    name: "affiliate_checkout_start", source: "link", policyVersion: row.policy_version,
    experimentKey: row.experiment_key, variant: row.variant,
  });
}
async function associateFunnelExperimentSignup(c: any, accountId: number, signingSecrets: string[], now: number): Promise<void> {
  try {
    const experiment = await readReferralExperiment(c.req.raw, signingSecrets, now);
    if (experiment) await associateFunnelExperimentSignupInDb(c.env.DB, experiment.assignment.journeyId, accountId, now);
  } catch (error) {
    console.error(JSON.stringify({ message: "Funnel Experiment signup association failed", accountId, error: error instanceof Error ? error.message : String(error) }));
  }
}
async function recordAffiliateConversion(c: any, accountId: number, provider: "stripe" | "nowpayments"): Promise<void> {
  const attribution = await c.env.DB.prepare(
    `SELECT attribution.affiliate_id, attribution.source, attribution.policy_version,
            account.signup_country, assignment.experiment_key, assignment.variant
       FROM affiliate_attributions AS attribution
       JOIN accounts AS account ON account.id = attribution.referred_account_id
       LEFT JOIN funnel_experiment_assignments AS assignment
         ON assignment.account_id = attribution.referred_account_id AND assignment.excluded_at IS NULL
      WHERE attribution.referred_account_id = ?`,
  ).bind(accountId).first() as {
    affiliate_id: number;
    source: "link" | "code";
    policy_version: string;
    signup_country: string | null;
    experiment_key: string | null;
    variant: "control" | "focused" | null;
  } | null;
  if (!attribution || analyticsConsentRequired(attribution.signup_country)) return;
  recordAffiliateFunnelEvent(c.env, attribution.affiliate_id, {
    name: "affiliate_conversion",
    source: attribution.source,
    provider,
    policyVersion: attribution.policy_version,
    experimentKey: attribution.experiment_key || undefined,
    variant: attribution.variant || undefined,
  });
}
app.get("/signup", async (c) => {
  if (await currentAccount(c)) {
    const tok = c.req.query("invite");
    if (tok) return c.redirect(`/admin/invite/${encodeURIComponent(tok)}`);
    return c.redirect("/admin");
  }
  const inviteToken = c.req.query("invite") || undefined;
  let inviteInfo: { title: string; role: string; email: string } | undefined;
  if (inviteToken) {
    const h = await sha256hex(inviteToken);
    const now = Math.floor(Date.now() / 1000);
    const row = await c.env.DB.prepare("SELECT i.email, i.role, t.title FROM blog_invitations i JOIN tenants t ON t.id = i.tenant_id WHERE i.token_hash = ? AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > ?").bind(h, now).first<{ email: string; role: string; title: string }>();
    if (row) inviteInfo = { title: row.title, role: row.role, email: row.email };
  }
  return c.html(signupPage(c.env.ROOT_DOMAIN, undefined, undefined, inviteToken, inviteInfo));
});

app.get("/admin/impersonate", async (c) => {
  const token = String(c.req.query("token")||"").trim();
  if (!token) return c.text("Missing token", 400);
  const now = Math.floor(Date.now()/1000);
  const tokenHash = await sha256hex(token);
  let row: any = null;
  try { row = await c.env.DB.prepare("SELECT token, account_id, expires_at, used_at FROM staff_impersonation_tokens WHERE token=?").bind(tokenHash).first() as any; } catch { return c.text("Impersonation not configured", 500); }
  if (!row) return c.text("Invalid token", 404);
  if (row.used_at) return c.text("Token already used", 410);
  if (row.expires_at < now) return c.text("Token expired", 410);
  try { await c.env.DB.prepare("UPDATE staff_impersonation_tokens SET used_at=? WHERE token=?").bind(now, tokenHash).run(); } catch {}
  const session = await createSession(c.env.DB, row.account_id);
  try { await c.env.DB.prepare("UPDATE sessions SET created_via='impersonation' WHERE token=?").bind(session).run(); } catch {}
  setSessionCookie(c, session);
  return c.redirect("/admin");
});
app.post("/signup", async (c) => {
  if (await currentAccount(c)) return c.redirect("/admin");
  const ip = getClientIp(c);
  const form = await c.req.formData();
  const slug = String(form.get("slug") ?? "").trim().toLowerCase();
  const title = String(form.get("title") ?? "").trim();
  const email = String(form.get("email") ?? "").trim().toLowerCase();
  const password = String(form.get("password") ?? "");
  const inviteToken = String(form.get("invite") ?? "").trim();
  const values = { slug, title, email };
  // Rate limit: 5/hour per IP, 3/hour per email
  const rl = await checkSignupRateLimit(c, ip, email);
  if (!rl.allowed) {
    const msg = `Too many signups — try again in ${Math.ceil((rl.retryAfter||3600)/60)} minutes.`;
    const failRL = (m: string) => c.html(signupPage(c.env.ROOT_DOMAIN, values, m, inviteToken || undefined, undefined), 429);
    return failRL(msg);
  }
  let __inviteInfo: { title: string; role: string; email: string } | undefined;
  if (inviteToken) {
    const __h = await sha256hex(inviteToken);
    const __now = Math.floor(Date.now() / 1000);
    const __row = await c.env.DB.prepare("SELECT i.email, i.role, t.title FROM blog_invitations i JOIN tenants t ON t.id = i.tenant_id WHERE i.token_hash = ?").bind(__h).first<{ email: string; role: string; title: string }>();
    if (__row) __inviteInfo = { title: __row.title, role: __row.role, email: __row.email };
  }
  const fail = (msg: string, status: 400 | 409 = 400) =>
    c.html(signupPage(c.env.ROOT_DOMAIN, values, msg, inviteToken || undefined, __inviteInfo), status);

  type SignupInvite = { id: number; tenant_id: number; email: string; role: MembershipRole };
  let invite: SignupInvite | null = null;
  if (inviteToken) {
    const now = Math.floor(Date.now() / 1000);
    invite = await c.env.DB.prepare("SELECT id, tenant_id, email, role FROM blog_invitations WHERE token_hash = ? AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at > ?")
      .bind(await sha256hex(inviteToken), now).first<SignupInvite>();
    if (!invite) return fail("This invitation is invalid or has expired.", 400);
    if (invite.email !== email) return fail(`Use the invited email address: ${invite.email}`, 400);
  }

  if (!invite) {
    const slugError = validateSlug(slug);
    if (slugError) return fail(slugError);
    if (!title) return fail("Please enter a blog title.");
  }
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))
    return fail("Please enter a valid email address.");
  if (password.length < 8)
    return fail("Password must be at least 8 characters.");

  // Pre-check uniqueness for friendly errors (DB constraints are the backstop).
  if (!invite && await c.env.DB.prepare("SELECT 1 FROM tenants WHERE slug = ?").bind(slug).first())
    return fail("That address is already taken.", 409);
  if (await c.env.DB.prepare("SELECT 1 FROM accounts WHERE email = ?").bind(email).first())
    return fail("That email already has an account.", 409);

  const now = Math.floor(Date.now() / 1000);

  // Create the account first; if the email raced us, stop before making a blog.
  let accountId: number;
  try {
    const pw_hash = await hashPassword(password);
    const res = await c.env.DB.prepare(
      "INSERT INTO accounts (email, pw_hash, created_at) VALUES (?, ?, ?)"
    )
      .bind(email, pw_hash, now)
      .run();
    accountId = res.meta.last_row_id as number;
  } catch {
    return fail("That email already has an account.", 409);
  }

  if (invite) {
    await c.env.DB.prepare("INSERT INTO memberships (account_id, tenant_id, role, created_at) VALUES (?, ?, ?, ?) ON CONFLICT(account_id, tenant_id) DO UPDATE SET role = excluded.role")
      .bind(accountId, invite.tenant_id, invite.role, now).run();
    const affiliateCookieSecrets = String(c.env.AFFILIATE_REFERRAL_COOKIE_SECRETS || "").split(",").map((secret) => secret.trim()).filter(Boolean);
    if (affiliateCookieSecrets.length) {
      const capturedReferral = await captureSignupReferral(c.req.raw, c.env.DB, accountId, affiliateCookieSecrets, now);
      if (capturedReferral.accepted) {
        await associateFunnelExperimentSignup(c, accountId, affiliateCookieSecrets, now);
        await recordAffiliateSignup(c, accountId);
      }
    }
    await c.env.DB.prepare("UPDATE blog_invitations SET accepted_at = ? WHERE id = ?").bind(now, invite.id).run();
    const tenant = await c.env.DB.prepare("SELECT public_id, title FROM tenants WHERE id = ?").bind(invite.tenant_id).first<{ public_id: string; title: string }>();
    if (tenant) {
      const invitation = invitationWelcomeEmail({ signInUrl: `https://www.blognice.com/admin/b/${tenant.public_id}`, blogTitle: tenant.title, role: invite.role });
      c.executionCtx.waitUntil(sendEmail(c.env, { to: email, ...invitation }));
    }
    await createEmailVerification(c, accountId, email, tenant?.title);
    const token = await createSession(c.env.DB, accountId);
    try { const ip = getClientIp(c); const ua = String(c.req.header('User-Agent')||'').slice(0,300); const ref = String(c.req.header('Referer')||'').slice(0,500); const country = String(c.req.header('CF-IPCountry')||'').slice(0,2); await c.env.DB.prepare('UPDATE sessions SET ip=?, user_agent=?, created_via="signup" WHERE token=?').bind(ip, ua, token).run(); try { await c.env.DB.prepare('UPDATE accounts SET signup_ip=?, signup_ua=?, signup_referer=?, signup_country=? WHERE id=?').bind(ip, ua, ref, country, accountId).run(); } catch { try { await c.env.DB.prepare('UPDATE accounts SET signup_ip=?, signup_ua=?, signup_referer=? WHERE id=?').bind(ip, ua, ref, accountId).run(); } catch {} } } catch {}
    clearSessionCookie(c);
    setSessionCookie(c, token);
    if (!emailEnabled(c.env)) return c.redirect(`/admin/b/${tenant?.public_id ?? ""}`);
    return c.html(verificationPendingPage(email));
  }

  // Create the blog and link it to the account.
  let blogId: number;
  const publicId = newPublicId();
  try {
    const res = await c.env.DB.prepare(
      "INSERT INTO tenants (public_id, slug, title, description, shard, browser_push_enabled, created_at) VALUES (?, ?, ?, '', 'primary', 1, ?)"
    )
      .bind(publicId, slug, title, now)
      .run();
    blogId = res.meta.last_row_id as number;
  } catch {
    // Roll back the account so we don't leave one with no blog.
    await c.env.DB.prepare("DELETE FROM accounts WHERE id = ?").bind(accountId).run();
    return fail("That address is already taken.", 409);
  }
  await c.env.DB.prepare(
    "INSERT INTO memberships (account_id, tenant_id, role, created_at) VALUES (?, ?, 'owner', ?)"
  )
    .bind(accountId, blogId, now)
    .run();
  c.executionCtx.waitUntil(purgeMasterSitemap(c.env).catch(() => {}));
  const affiliateCookieSecrets = String(c.env.AFFILIATE_REFERRAL_COOKIE_SECRETS || "").split(",").map((secret) => secret.trim()).filter(Boolean);
  if (affiliateCookieSecrets.length) {
    const capturedReferral = await captureSignupReferral(c.req.raw, c.env.DB, accountId, affiliateCookieSecrets, now);
    if (capturedReferral.accepted) {
      await associateFunnelExperimentSignup(c, accountId, affiliateCookieSecrets, now);
      await recordAffiliateSignup(c, accountId);
    }
  }
  await createEmailVerification(c, accountId, email, title);
  c.executionCtx.waitUntil(sendEmail(c.env, { to: email, ...registrationWelcomeEmail({ signInUrl: "https://www.blognice.com/admin" }) }));
  const token = await createSession(c.env.DB, accountId);
  try { const ip = getClientIp(c); const ua = String(c.req.header('User-Agent')||'').slice(0,300); const ref = String(c.req.header('Referer')||'').slice(0,500); await c.env.DB.prepare('UPDATE sessions SET ip=?, user_agent=?, created_via="signup" WHERE token=?').bind(ip, ua, token).run(); try { await c.env.DB.prepare('UPDATE accounts SET signup_ip=?, signup_ua=?, signup_referer=? WHERE id=?').bind(ip, ua, ref, accountId).run(); } catch {} } catch {}
  clearSessionCookie(c);
  setSessionCookie(c, token);
  if (!emailEnabled(c.env)) return c.redirect(`/admin/b/${publicId}`);
  return c.html(verificationPendingPage(email));
});

app.get("/verify-pending", async (c) => {
  const acct = await currentAccount(c);
  const email = acct?.email || String(c.req.query("email")||"");
  if (!email) return c.redirect("/signup");
  if (acct && isEmailVerified(acct) && emailEnabled(c.env)) return c.redirect("/admin");
  return c.html(verificationPendingPage(email));
});
app.get("/verify-email", async (c) => {
  const token = String(c.req.query("token")||"").trim();
  if (!token) return c.html(verificationResultPage(false, "Missing token."), 400);
  const ipVerify = `verify:${getClientIp(c)}`;
  const rlVerify = await checkSignupRateLimit(c, ipVerify, ipVerify);
  if (!rlVerify.allowed) return c.html(shell(`Too many requests — blognice`, `<div class="page narrow"><h1>Too many requests</h1><p>Verification is rate-limited — try again in ${Math.ceil((rlVerify.retryAfter||3600)/60)} minutes.</p><p><a href="/verify-pending">Back</a></p></div>`), 429);
  const hash = await sha256hex(token);
  const now = Math.floor(Date.now()/1000);
  const row = await c.env.DB.prepare("SELECT account_id, expires_at FROM account_email_verifications WHERE token_hash=?").bind(hash).first<{ account_id:number; expires_at:number }>();
  if (!row || row.expires_at < now) return c.html(verificationResultPage(false), 400);
  await c.env.DB.batch([
    c.env.DB.prepare("UPDATE accounts SET email_verified=1, email_verified_at=? WHERE id=?").bind(now, row.account_id),
    c.env.DB.prepare("DELETE FROM account_email_verifications WHERE account_id=?").bind(row.account_id),
  ]);
  const acct = await c.env.DB.prepare("SELECT email FROM accounts WHERE id=?").bind(row.account_id).first<{ email:string }>();
  if (acct?.email) c.executionCtx.waitUntil(sendEmail(c.env, { to: acct.email, ...registrationWelcomeEmail({ signInUrl: "https://www.blognice.com/admin", greeting: "Your email is verified — welcome!" }) }));
  return c.html(verificationResultPage(true));
});
app.post("/verify-email/resend", async (c) => {
  const form = await c.req.formData().catch(()=>null);
  let email = String(form?.get("email")||c.req.query("email")||"").trim().toLowerCase();
  if (!email) {
    const acct = await currentAccount(c);
    email = acct?.email || "";
  }
  if (!email) return c.html(verificationPendingPage("your email", true));
  const ipResend = getClientIp(c);
  const rlResend = await checkSignupRateLimit(c, ipResend, email);
  if (!rlResend.allowed) return c.html(shell(`Too many requests — blognice`, `<div class="page narrow"><h1>Too many requests</h1><p>Resend is rate-limited — try again in ${Math.ceil((rlResend.retryAfter||3600)/60)} minutes.</p><p><a href="/verify-pending">Back</a></p></div>`), 429);
  const acct = await c.env.DB.prepare("SELECT id, email_verified FROM accounts WHERE email=?").bind(email).first<{ id:number; email_verified:number }>();
  if (!acct) return c.html(verificationPendingPage(email, true));
  if (Number(acct.email_verified)===1) return c.html(verificationPendingPage(email, true));
  const tenant = await c.env.DB.prepare("SELECT title FROM tenants JOIN memberships ON memberships.tenant_id=tenants.id WHERE memberships.account_id=? LIMIT 1").bind(acct.id).first<{ title:string }>().catch(()=>null);
  await createEmailVerification(c, acct.id, email, tenant?.title);
  return c.html(verificationPendingPage(email, true));
});

