function legalPage(c: any, page: string): Response {
  const host = new URL(c.req.url).hostname.toLowerCase();
  if (host !== `www.${c.env.ROOT_DOMAIN}`.toLowerCase()) return c.redirect(`https://www.${c.env.ROOT_DOMAIN}${new URL(c.req.url).pathname}`, 301);
  const currentPath = new URL(c.req.url).pathname;
  const policyItems = [["/policies", "All policies"], ["/privacy", "Privacy"], ["/terms", "Terms"], ["/affiliate-terms", "Affiliate Terms"], ["/cookies", "Cookies"], ["/security", "Security"]] as const;
  const policyNav = `<nav class="policy-nav" aria-label="Policy pages">${policyItems.map(([href, label]) => `<a href="${href}"${currentPath === href ? ' aria-current="page"' : ""}>${label}</a>`).join("")}</nav>`;
  const policyNavMarkup = policyItems.some(([href]) => href === currentPath) ? policyNav : "";
  const consistentTheme = page
    .replaceAll("https://www.blognice.com/", "/")
    .replace("</style>", ".theme-toggle{width:2.35rem;height:2.35rem;display:inline-flex;align-items:center;justify-content:center;border-radius:999px;padding:0;line-height:1}.theme-toggle .moon{display:none}html[data-theme=dark] .theme-toggle .sun{display:none}html[data-theme=dark] .theme-toggle .moon{display:inline}</style>")
    .replace('<button id="theme-toggle" type="button">◐ Theme</button>', '<button id="theme-toggle" class="theme-toggle" type="button" aria-label="Use dark theme" aria-pressed="false" title="Use dark theme"><span class="sun" aria-hidden="true">☀</span><span class="moon" aria-hidden="true">☾</span></button>')
    .replaceAll('href="mailto:security@blognice.com">Security', 'href="/security">Security')
    .replaceAll('href="mailto:privacy@blognice.com">Contact privacy', 'href="/privacy">Privacy')
    .replaceAll('href="mailto:privacy@blognice.com">Contact', 'href="/privacy">Privacy')
    .replace("</style>", "html{scrollbar-gutter:stable}body{overflow-y:scroll}.policy-nav{display:flex;align-items:center;gap:.2rem;min-width:0;overflow-x:auto;scrollbar-width:none;margin:1rem 0 1.5rem;padding:0;font:14px/1.5 var(--sans)}.policy-nav::-webkit-scrollbar{display:none}.policy-nav a{flex:0 0 auto;padding:.5rem .75rem;border-radius:7px;color:var(--muted);font-weight:600;text-decoration:none;white-space:nowrap}.policy-nav a:hover,.policy-nav a:focus-visible{color:var(--ink);background:var(--bg)}.policy-nav a[aria-current=page]{color:var(--accent);background:color-mix(in srgb,var(--accent) 12%,transparent)}:root{--bg:#fdfdfc;--panel:#fff;--ink:#1a1a18;--muted:#6a6a66;--rule:#e4e3de;--accent:#146b54;--accent-ink:#fff;--sans:system-ui,-apple-system,\"Segoe UI\",Roboto,Helvetica,Arial,sans-serif}html[data-theme=dark]{--bg:#161614;--panel:#1e1e1b;--ink:#e9e8e3;--muted:#9a9a93;--rule:#302f2b;--accent:#6fc9a9;--accent-ink:#10241d}body{background:var(--bg);color:var(--ink);font:15px/1.5 var(--sans);-webkit-font-smoothing:antialiased}main,.wrap{width:min(760px,calc(100% - 2rem));max-width:none;margin:0 auto;padding:0 0 5rem}.top,.topbar{min-height:3.5rem;padding:.8rem max(1rem,calc((100vw - 760px)/2));margin-left:calc(50% - 50vw);margin-right:calc(50% - 50vw);border-bottom:1px solid var(--rule);background:var(--panel)}.top a,.topbar a{color:var(--accent)}.topbar + a.meta{display:none}h1,h2,h3{font-family:var(--sans);line-height:1.2}h1{font-size:clamp(2rem,4vw,2.8rem);margin:3rem 0 .8rem}h2{font-size:1.35rem;margin:2.25rem 0 .65rem}h3{font-size:1.05rem;margin:1.35rem 0 .45rem}p,li{max-width:54rem}a{color:var(--accent)}.footer{border-top:1px solid var(--rule);margin:2.5rem auto 0;padding:1.25rem 0 2rem;display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap;color:var(--muted);font:13px/1.5 var(--sans)}.footer a{color:inherit}.footer a:hover,.footer a:focus-visible{color:var(--accent);text-decoration:underline}.footer-links{display:flex;gap:1rem;flex-wrap:wrap}@media(max-width:640px){main,.wrap{width:calc(100% - 2rem)}.footer{align-items:flex-start;flex-direction:column}.footer a{padding:.35rem 0}}</style>")
    .replace('<a href="/privacy">Privacy</a>', '')
    .replace('<h1>', `${policyNavMarkup}<h1>`)
    .replaceAll("© blognice · Pragmatic Online Co., Ltd.", "© 2026 blognice · Pragmatic Online Co., Ltd.")
    .replace("</nav></footer>", '<a href="/privacy#analytics-dialog">Analytics preferences</a></nav></footer>');
  const canonicalFooter = '<footer class="footer"><span>© 2026 blognice · Pragmatic Online Co., Ltd.</span><nav class="footer-links" aria-label="Legal"><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="/cookies">Cookies</a><a href="/security">Security</a><a href="/privacy#analytics-dialog">Analytics preferences</a></nav></footer>';
  const withCanonicalShell = consistentTheme.replace(/<footer class="footer">[\s\S]*?<\/footer>/, canonicalFooter);
  const withFounderTerms = page === termsPage
    ? withCanonicalShell.replace('<h2>4. Your content', '<p><strong>Founder pricing:</strong> US$5 per month, billed monthly, or US$36 per year, billed annually, plus applicable taxes. Your subscription renews at the price and billing interval selected for as long as it remains continuously active. If you cancel, allow it to lapse, or switch to another plan, the founder rate ends; a later subscription uses the then-current price. We may offer different prices to later subscribers.</p><h2>4. Your content')
    : withCanonicalShell;
  const withPrivacyPreferences = page === privacyPage
    ? withFounderTerms.replace("</body>", '<script>if(location.hash==="#analytics-dialog"){var analyticsDialog=document.getElementById("analytics-dialog");if(analyticsDialog)analyticsDialog.hidden=false}</script></body>')
    : withFounderTerms;
  return new Response(withPrivacyPreferences, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store, max-age=0" } });
}

