function subscriptionManagePage(email: string, subscriptions: Array<{ id: number; title: string; slug: string; custom_domain?: string | null }>, token: string, message = ""): string {
  const rows = subscriptions.length
    ? subscriptions.map((subscription) => `<label style="display:block;padding:.7rem 0;border-bottom:1px solid #e3e7dd"><input type="checkbox" name="subscription" value="${subscription.id}" checked> <strong>${esc(subscription.title)}</strong><br><small style="color:#687064;margin-left:1.5rem">${esc(subscription.custom_domain || `${subscription.slug}.blognice.com`)}</small></label>`).join("")
    : `<p>You are not subscribed to any blognice blogs.</p>`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage subscriptions · blognice</title><style>body{margin:0;background:#f7f8f3;color:#171914;font:16px/1.6 system-ui,-apple-system,Segoe UI,sans-serif}.card{max-width:620px;margin:8vh auto;padding:2rem;background:#fff;border:1px solid #dfe4da;border-radius:10px}h1{margin-top:0}small,.muted{color:#687064}.btn{margin-top:1.2rem;padding:.65rem 1rem;border:1px solid #dfe4da;border-radius:6px;background:#171914;color:#fff;font:inherit;cursor:pointer}.notice{padding:.7rem;background:#eaf4e8;border-radius:6px}</style></head><body><main class="card"><p class="muted">blognice</p><h1>Manage subscriptions</h1><p>Subscriptions for <strong>${esc(email)}</strong></p>${message ? `<p class="notice">${esc(message)}</p>` : ""}<form method="post" action="/manage-subscriptions/${esc(token)}">${rows}${subscriptions.length ? `<button class="btn" type="submit">Save preferences</button>` : ""}</form></main></body></html>`;
}

async function processEmailFanout(env: Bindings, job: EmailFanoutMessage): Promise<void> {
  if (!env.EMAIL_QUEUE) throw new Error("Email queue is not configured.");
  const tenant = await tenantById(env, job.tenantId);
  if (!tenant) return;
  const post = await tenantDb(env, tenant).prepare(
    "SELECT title, body_md, featured_image_key, author_name, author_visible, created_at FROM posts WHERE tenant_id = ? AND slug = ? AND published = 1"
  ).bind(tenant.id, job.postSlug).first<{ title: string; body_md: string; featured_image_key?: string | null; author_name?: string | null; author_visible?: number; created_at: number }>();
  if (!post) return;
  const subscribers = await env.DB.prepare("SELECT id, email, token FROM subscribers WHERE tenant_id = ? AND confirmed_at IS NOT NULL AND id > ? ORDER BY id LIMIT 100")
    .bind(job.tenantId, job.afterId).all<{ id: number; email: string; token: string }>();
  const origin = publicOrigin(env, tenant);
  const postUrl = `${origin}/${job.postSlug}`;
  const imageUrl = post.featured_image_key ? `${origin}/media/${post.featured_image_key}` : "";
  const excerpt = post.body_md.replace(/```[\s\S]*?```/g, " ").replace(/^[=\-]{3,}\s*$/gm, " ").replace(/[#>*_`\[\]()>=-]/g, " ").replace(/\s+/g, " ").trim().slice(0, 220);
  const author = post.author_visible && post.author_name ? `By ${post.author_name}` : "";
  const publishedLabel = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" }).format(new Date(post.created_at * 1000));
  const deliveries: EmailJobMessage[] = [];
  for (const subscriber of subscribers.results) {
    try { const sup = await env.DB.prepare("SELECT 1 FROM email_suppressions WHERE email = ? LIMIT 1").bind(subscriber.email.toLowerCase()).first(); if (sup) continue; } catch {}
    const unsub = `${origin}/unsubscribe/${subscriber.token}`;
    const manageUrl = subscriptionManageUrl(env, await subscriptionManageToken(env, subscriber.email));
    deliveries.push({
      kind: "email-delivery",
      idempotencyKey: `post:${job.campaignId}:${subscriber.id}`,
      subscriberId: subscriber.id,
      to: subscriber.email,
      tag: String(job.tenantId),
      senderName: tenant.title,
      ...postNotificationEmail({ blogTitle: tenant.title, postTitle: job.postTitle, postUrl, imageUrl, authorLabel: author || undefined, publishedLabel, readingMinutes: Math.max(1, Math.ceil(post.body_md.split(/\s+/).filter(Boolean).length / 200)), excerpt, unsubscribeUrl: unsub, manageUrl }),
    });
  }
  if (deliveries.length) await env.EMAIL_QUEUE.sendBatch(deliveries.map((body) => ({ body })));
  if (subscribers.results.length === 100) await env.EMAIL_QUEUE.send({ ...job, afterId: subscribers.results[subscribers.results.length - 1].id });
}

async function processPushFanout(env: Bindings, job: PushFanoutMessage): Promise<void> {
  if (!env.PUSH_QUEUE) throw new Error("Browser push queue is not configured.");
  const tenant = await tenantById(env, job.tenantId);
  if (!tenant) return;
  if (!tenant.browser_push_enabled) return;
  if (!pushConfigured(env)) throw new Error("Browser push is enabled but VAPID configuration is missing.");
  const campaign = await env.DB.prepare("SELECT post_slug, post_title, post_excerpt, max_subscription_id, status FROM push_campaigns WHERE campaign_id = ? AND tenant_id = ? AND topic = 'new-post'").bind(job.campaignId, tenant.id).first<{ post_slug: string; post_title: string; post_excerpt: string; max_subscription_id: number; status: string }>();
  if (!campaign || campaign.status === "completed" || campaign.status === "failed" || campaign.status === "retry-exhausted") return;
  const subscriptions = await env.DB.prepare("SELECT id, endpoint, p256dh, auth FROM push_subscriptions WHERE tenant_id = ? AND topic = 'new-post' AND id > ? AND id <= ? ORDER BY id LIMIT 50")
    .bind(tenant.id, job.afterId, campaign.max_subscription_id).all<{ id: number; endpoint: string; p256dh: string; auth: string }>();
  const payload: PushPayload = {
    title: `New post on ${tenant.title}`,
    body: `${campaign.post_title}${campaign.post_excerpt ? ` — ${campaign.post_excerpt}` : ""}`,
    url: `${publicOrigin(env, tenant)}/${campaign.post_slug}`,
    tag: `blognice-post-${campaign.post_slug}`,
  };
  let lastId = job.afterId;
  let retryableFailure = false;
  let campaignFailure = false;
  for (const subscription of subscriptions.results) {
    lastId = subscription.id;
    const now = Math.floor(Date.now() / 1000);
    await env.DB.prepare("INSERT OR IGNORE INTO push_deliveries (campaign_id, subscription_id, status, attempts) VALUES (?, ?, 'pending', 0)").bind(job.campaignId, subscription.id).run();
    const claim = await env.DB.prepare("UPDATE push_deliveries SET status = 'claimed', claimed_at = ?, attempts = attempts + 1 WHERE campaign_id = ? AND subscription_id = ? AND (status = 'pending' OR (status = 'claimed' AND claimed_at < ?))").bind(now, job.campaignId, subscription.id, now - 300).run();
    if (claim.meta.changes !== 1) continue;
    try {
      const status = await sendBrowserPush(env, { endpoint: subscription.endpoint, keys: { p256dh: subscription.p256dh, auth: subscription.auth } }, payload);
      const disposition = classifyPushDelivery(status);
      if (disposition === "sent") {
        await env.DB.prepare("UPDATE push_deliveries SET status = 'sent', sent_at = ? WHERE campaign_id = ? AND subscription_id = ?").bind(Math.floor(Date.now() / 1000), job.campaignId, subscription.id).run();
        await env.DB.prepare("UPDATE push_subscriptions SET last_success_at = ?, updated_at = ? WHERE id = ? AND tenant_id = ?").bind(Math.floor(Date.now() / 1000), Math.floor(Date.now() / 1000), subscription.id, tenant.id).run();
        try { recordCustomEvent(env as any, tenant.id, { name: "push_delivered", path: "/" + job.postSlug, visitor: "", country: "", device: "", browser: "" }); } catch {}
      } else if (disposition === "expired") await env.DB.prepare("DELETE FROM push_subscriptions WHERE id = ? AND tenant_id = ?").bind(subscription.id, tenant.id).run();
    } catch (error) {
      const status = Number((error as { statusCode?: number }).statusCode || 0);
      const disposition = classifyPushDelivery(status);
      if (disposition === "expired") await env.DB.prepare("DELETE FROM push_subscriptions WHERE id = ? AND tenant_id = ?").bind(subscription.id, tenant.id).run();
      else if (disposition === "retry") {
        retryableFailure = true;
        await env.DB.prepare("UPDATE push_deliveries SET status = 'pending', claimed_at = NULL WHERE campaign_id = ? AND subscription_id = ?").bind(job.campaignId, subscription.id).run();
      } else if (disposition === "campaign-failed") {
        campaignFailure = true;
        await env.DB.prepare("UPDATE push_deliveries SET status = 'dead' WHERE campaign_id = ? AND subscription_id = ?").bind(job.campaignId, subscription.id).run();
      } else await env.DB.prepare("UPDATE push_deliveries SET status = 'dead' WHERE campaign_id = ? AND subscription_id = ?").bind(job.campaignId, subscription.id).run();
    }
  }
  if (campaignFailure) {
    await env.DB.prepare("UPDATE push_campaigns SET status = 'failed', completed_at = NULL WHERE campaign_id = ? AND tenant_id = ?").bind(job.campaignId, tenant.id).run();
    return;
  }
  if (retryableFailure) throw new Error("One or more browser push deliveries are retryable.");
  if (subscriptions.results.length === 50) await env.PUSH_QUEUE.send({ ...job, afterId: lastId });
  else await env.DB.prepare("UPDATE push_campaigns SET status = 'completed', completed_at = ? WHERE campaign_id = ? AND tenant_id = ? AND status = 'pending'").bind(Math.floor(Date.now() / 1000), job.campaignId, tenant.id).run();
}

async function cleanupPushState(env: Bindings): Promise<void> {
  const now = Math.floor(Date.now() / 1000);
  await env.DB.batch([
    env.DB.prepare("DELETE FROM push_subscription_limits WHERE window_start < ?").bind(now - 172800),
    env.DB.prepare("DELETE FROM push_deliveries WHERE sent_at IS NOT NULL AND sent_at < ?").bind(now - 2592000),
    env.DB.prepare("DELETE FROM push_subscriptions WHERE (last_success_at IS NOT NULL AND last_success_at < ?) OR (last_success_at IS NULL AND updated_at < ?) OR (tenant_id IN (SELECT id FROM tenants WHERE browser_push_enabled = 0) AND updated_at < ?)").bind(now - 7776000, now - 7776000, now - 2592000),
  ]);
}

async function processEmailJob(env: Bindings, job: EmailJobMessage): Promise<void> {
  if (job.to) {
    try { const suppressed = await env.DB.prepare("SELECT 1 FROM email_suppressions WHERE email = ? LIMIT 1").bind(job.to.toLowerCase()).first(); if (suppressed) return; } catch {}
  }
  if (job.subscriberId != null) {
    const active = await env.DB.prepare("SELECT id FROM subscribers WHERE id = ? AND confirmed_at IS NOT NULL").bind(job.subscriberId).first();
    if (!active) return;
  }
  const existing = await env.DB.prepare("SELECT status FROM email_delivery_log WHERE idempotency_key = ?")
    .bind(job.idempotencyKey).first<{ status: string }>();
  if (existing?.status === "sent") return;
  const now = Math.floor(Date.now() / 1000);
  await env.DB.prepare(
    `INSERT INTO email_delivery_log (idempotency_key, status, recipient, kind, created_at)
     VALUES (?, 'pending', ?, ?, ?)
     ON CONFLICT(idempotency_key) DO UPDATE SET status = 'pending'`
  ).bind(job.idempotencyKey, job.to, job.emailKind || "post-notification", now).run();
  if (!await sendEmail(env, { ...job, tag: (job as any).tag } as any)) throw new Error("transactional email provider rejected the message");
  await env.DB.prepare("UPDATE email_delivery_log SET status = 'sent', sent_at = ? WHERE idempotency_key = ?")
    .bind(Math.floor(Date.now() / 1000), job.idempotencyKey).run();
}

app.get("/manage-subscriptions/:token", async (c) => {
  const token = c.req.param("token");
  const identity = await c.env.DB.prepare("SELECT email FROM subscription_manage_tokens WHERE token = ?")
    .bind(token).first<{ email: string }>();
  if (!identity) return c.html(subscriptionManagePage("unknown address", [], token, "This link is invalid or has expired."), 404);
  const subscriptions = await c.env.DB.prepare("SELECT s.id, t.title, t.slug, t.custom_domain FROM subscribers s JOIN tenants t ON t.id = s.tenant_id WHERE s.email = ? AND s.confirmed_at IS NOT NULL ORDER BY t.title")
    .bind(identity.email).all<{ id: number; title: string; slug: string; custom_domain?: string | null }>();
  return c.html(subscriptionManagePage(identity.email, subscriptions.results, token));
});

app.get("/admin/b/:blogId/audit", async (c) => {
  const ctx = await blogContext(c);
  if ("redirect" in ctx) return c.redirect(ctx.redirect);
  if ("suspended" in ctx) return suspendedResponse(c, ctx.account);
  if (!(await tenantHasPaidPlan(c.env, ctx.tenant.id)))
    return c.html(auditPage(ctx.account, ctx.tenant, [], { paid: false }), 402);
  try {
    const raw = String(c.req.query("page") || "1");
    const parsed = Number(raw);
    const page = Number.isSafeInteger(parsed) && parsed >= 1 && parsed <= 10_000_000 ? parsed : 1;
    const { entries, hasMore } = await auditReport(c.env, ctx.tenant.id, 90, page, 50);
    return c.html(auditPage(ctx.account, ctx.tenant, entries, { paid: true, page, hasMore }));
  } catch (error) {
    console.error("audit report failed", error);
    return c.html(auditPage(ctx.account, ctx.tenant, null, { error: "Audit log could not be loaded. Please try again shortly.", paid: true }), 502);
  }
});

function billingPage(
  account: Account,
  billing: any,
  message = "",
  credits?: { used: number; allowance: number },
  prices?: { monthly?: string; yearly?: string },
  cryptoReady = false,
  attributed = false,
): string {
  const status = String(billing.billing_status || "inactive");
  const stripeActive = ["active", "trialing", "past_due"].includes(status);
  const cryptoActive = Number(billing.crypto_paid_through || 0) > Math.floor(Date.now() / 1000);
  const vipActive = Number(billing.vip_granted_at || 0) > 0 && (billing.vip_expires_at == null || Number(billing.vip_expires_at) > Math.floor(Date.now() / 1000));
  const active = stripeActive || cryptoActive || vipActive;
  const vipExpiryLabel = vipActive ? (billing.vip_expires_at ? ` · valid through ${new Date(Number(billing.vip_expires_at) * 1000).toLocaleDateString()}` : ` · lifetime`) : "";
  const cryptoPriceMinor = affiliateAnnualPriceMinor(attributed, NOWPAYMENTS_ANNUAL_USD * 100);
  const allowance = Math.max(0, Number(credits?.allowance || AI_MONTHLY_CREDITS));
  const used = Math.min(allowance, Math.max(0, Number(credits?.used || 0)));
  const remaining = allowance - used;
  const period = aiCreditPeriod();
  const [periodYear, periodMonth] = period.split("-").map(Number);
  const resetDate = Number.isFinite(periodYear) && Number.isFinite(periodMonth)
    ? new Date(Date.UTC(periodYear, periodMonth, 1)).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" })
    : "the start of next month";
  const term = billing.billing_price_id === prices?.monthly ? "monthly" : billing.billing_price_id === prices?.yearly ? "yearly" : "";
  const renewal = billing.billing_period_end
    ? `${billing.billing_cancel_at_period_end ? "Ends" : "Renews"} ${new Date(Number(billing.billing_period_end) * 1000).toLocaleDateString()}`
    : "";
  const check = `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><path d="m5 13 4 4L19 7"/></svg>`;
  const freeFeatures = ["One blognice blog", "blognice subdomain", "Editor, publishing, and images", "RSS, themes, tags, and basic metrics"];
  // Free plan remains the default until a provider confirms payment.
  const proFeatures = ["Up to five blogs", "AI Markdown formatting, image generation, and audio narration", "Collaborators and authors", "Custom domains and favicons", "API access"];
  const features = (items: string[]) => `<ul class="billing-features">${items.map((item) => `<li>${check}${esc(item)}</li>`).join("")}</ul>`;
  const checkout = (plan: "monthly" | "yearly", label: string, cls = "") => `<form method="post" action="/admin/billing/checkout"><input type="hidden" name="plan" value="${plan}"><button class="billing-btn ${cls}" type="submit">${label}</button></form>`;
  const portal = `<form method="post" action="/admin/billing/portal"><button class="billing-btn billing-btn-solid" type="submit">Manage billing in Stripe</button></form>`;
  const vipNotice = vipActive ? `<div class="billing-notice" style="background:#fef9e7;border-color:#f5e6a3"><strong>VIP access</strong> — gifted membership, equivalent to Pro${esc(vipExpiryLabel)}.${billing.vip_reason ? ` <span class="muted">${esc(billing.vip_reason)}</span>` : ""}</div>` : "";
  const statusNotice = vipNotice || (status === "past_due"
    ? `<div class="billing-alert"><strong>Payment needs attention.</strong> Your Pro features remain available temporarily, but update your payment method in Stripe to avoid interruption.${billing.stripe_customer_id ? `<div class="billing-alert-action">${portal.replace("Manage billing in Stripe", "Fix payment in Stripe")}</div>` : ""}</div>`
    : message ? `<div class="billing-notice">${esc(message)}</div>` : "");
  const cryptoExpiry = cryptoActive ? new Date(Number(billing.crypto_paid_through) * 1000).toLocaleDateString() : "";
  const billingAction = vipActive ? "" : stripeActive ? portal : "";
  // const billingAction = stripeActive ? portal : ""
  const usage = active ? `<section class="billing-section billing-usage"><div class="billing-section-head"><h2>AI usage</h2><span>Resets ${esc(resetDate)}</span></div><div class="billing-usage-stat"><div class="billing-usage-icon">✦</div><div><strong>${remaining.toLocaleString()} of ${allowance.toLocaleString()}</strong><span>credits remaining this month</span></div></div><div class="billing-track"><div style="width:${allowance ? Math.round(used / allowance * 100) : 0}%"></div></div><div class="billing-bar-labels"><span>${used.toLocaleString()} used</span><span>${remaining.toLocaleString()} remaining</span></div><p class="billing-muted">Images use 3 credits. Audio narration uses credits based on word count.</p></section>` : "";
  const freeCard = `<article class="billing-plan ${!active ? "billing-current" : ""}"><div class="billing-plan-name">Free</div><div class="billing-price">$0</div>${!active ? `<span class="billing-current-badge">${check} Current plan</span>` : ""}<div class="billing-includes">What's included</div>${features(freeFeatures)}${!active ? `<span class="billing-plan-foot">This is your plan today</span>` : vipActive ? `<span class="billing-plan-foot">${check} Included with VIP</span>` : ""}</article>`;
  const monthlyCard = `<article class="billing-plan ${vipActive ? "billing-current" : stripeActive && term === "monthly" ? "billing-current" : ""}"><div class="billing-plan-name">${vipActive ? "VIP" : "blognice pro monthly"}</div><div class="billing-price">${vipActive ? "VIP" : "$5 <small>/ month</small>"}</div><p class="billing-sub">${vipActive ? "Gifted membership · equivalent to Pro" : "Founding member price · billed monthly, cancel any time"}</p><div class="billing-includes">Everything in Free, plus</div>${features(proFeatures)}${vipActive ? `<span class="billing-current-badge">${check} VIP active${esc(vipExpiryLabel)}</span><span class="billing-plan-foot">Your VIP includes all Pro features</span>` : stripeActive && term === "monthly" ? `<span class="billing-plan-foot">${check} Current plan${renewal ? ` · ${esc(renewal)}` : ""}</span>` : stripeActive ? `<span class="billing-plan-foot">Plan changes are managed in Stripe</span>` : cryptoActive ? `<span class="billing-plan-foot">Available with your crypto plan</span>` : checkout("monthly", "Choose $5/month", "billing-btn-dark")}</article>`;
  const yearlyCard = `<article class="billing-plan billing-featured ${vipActive ? "" : stripeActive && term === "yearly" ? "billing-current" : ""}"><span class="billing-ribbon">${vipActive ? "VIP" : "Founding price"}</span><div class="billing-plan-name">${vipActive ? "VIP" : "blognice pro yearly"}</div><div class="billing-price">${vipActive ? "VIP" : "$36 <small>/ year</small>"}</div><p class="billing-sub">${vipActive ? "Gifted membership · equivalent to Pro" : "Founding member price · just <b>$3/month</b>, billed annually"}</p><div class="billing-includes">Everything in Free, plus</div>${features(proFeatures)}${vipActive ? `<span class="billing-plan-foot">Covered by VIP — no payment needed</span>` : stripeActive && term === "yearly" ? `<span class="billing-plan-foot">${check} Current plan${renewal ? ` · ${esc(renewal)}` : ""}</span>` : stripeActive ? `<span class="billing-plan-foot">Plan changes are managed in Stripe</span>` : cryptoActive ? `<span class="billing-plan-foot">Available with your crypto plan</span>` : checkout("yearly", "Lock in $36/year", "billing-btn-green")}</article>`;
  // Keep literal for test: billing-ribbon">Founding price
  const cryptoOption = cryptoActive
    ? `<div class="crypto-option crypto-option-active">${check} Crypto plan active · valid through ${esc(cryptoExpiry)}</div>`
    : stripeActive
      ? `<div class="crypto-option crypto-option-muted">Crypto payment is available after your current Stripe subscription ends.</div>`
      : cryptoReady
      ? `<div class="crypto-option"><div class="crypto-option-copy"><strong>Or pay for blognice pro yearly with crypto</strong><span>One year prepaid · no automatic renewal${attributed ? " · 10% referral discount applied" : ""}</span><div class="crypto-assets" aria-label="Supported crypto assets"><span role="img" aria-label="Bitcoin">₿</span><span role="img" aria-label="Ethereum">Ξ</span><span role="img" aria-label="Tron">TRX</span><span role="img" aria-label="Tether USDT">₮</span></div></div><form method="post" action="/admin/billing/crypto/checkout"><button class="billing-btn billing-btn-crypto" type="submit">Pay $${(cryptoPriceMinor / 100).toFixed(2)} with crypto</button></form></div>`
      : `<div class="crypto-option crypto-option-muted">Crypto payments are being configured.</div>`;
  const unknownPaid = stripeActive && !term ? `<div class="billing-notice">Your Stripe subscription is active. Use Manage billing in Stripe to view its current plan and renewal details.</div>` : "";
  const formerCustomer = !active && billing.stripe_customer_id ? `<div class="billing-history">Already subscribed before? ${portal.replace("Manage billing in Stripe", "View billing history in Stripe")}</div>` : "";
  const referralCode = !active && !attributed
    ? `<section class="billing-section billing-referral"><div class="billing-section-head"><h2>Have a referral code?</h2></div><form method="post" action="/admin/billing/referral"><label for="referral-code">Referral code</label><div style="display:flex;gap:.6rem;margin-top:.4rem"><input id="referral-code" name="referral_code" required maxlength="64" autocomplete="off" style="min-width:0;flex:1;border:1px solid var(--rule);border-radius:9px;padding:.7rem;font:inherit"><button class="billing-btn" style="width:auto" type="submit">Apply code</button></div></form></section>`
    : "";
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Billing · Blog Nice</title><style>
  :root{--bg:#f7f8f3;--card:#fff;--ink:#15170f;--soft:#5c6455;--faint:#8a9182;--green:#1a8917;--deep:#0e5a0c;--mist:#eef5ec;--rule:#e3e7dd}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif;padding:3.5rem 1.5rem}.billing-wrap{max-width:1040px;margin:auto}.billing-crumb{color:var(--deep);font-weight:650;text-decoration:none;display:inline-block;margin-bottom:1.8rem}.billing-h1{font-size:30px;margin:0 0 .35rem;letter-spacing:-.02em}.billing-account{color:var(--soft);margin:0 0 2.2rem}.billing-account b{color:var(--ink)}.billing-alert,.billing-notice{padding:.85rem 1rem;border-radius:10px;margin:0 0 1.2rem}.billing-alert{background:#fff4e5;border:1px solid #e8c58c;color:#6b4300}.billing-notice{background:var(--mist);border:1px solid #cfe6cb;color:var(--deep)}.billing-section{margin:0 0 2.4rem}.billing-section-head{display:flex;justify-content:space-between;align-items:baseline;gap:1rem;margin-bottom:1rem}.billing-section-head h2{font-size:19px;margin:0}.billing-section-head span{font-size:13px;color:var(--faint)}.billing-usage{background:var(--card);border:1px solid var(--rule);border-radius:16px;padding:1.5rem 1.7rem}.billing-usage-stat{display:flex;align-items:center;gap:.8rem}.billing-usage-icon{width:2.4rem;height:2.4rem;border-radius:9px;background:var(--mist);color:var(--deep);display:grid;place-items:center;font-size:1.35rem}.billing-usage-stat strong{display:block;font-size:20px}.billing-usage-stat span{display:block;color:var(--soft);font-size:13px}.billing-track{height:8px;background:var(--rule);border-radius:99px;overflow:hidden;margin:1.2rem 0 .5rem}.billing-track div{height:100%;background:var(--green);border-radius:99px}.billing-bar-labels{display:flex;justify-content:space-between;color:var(--soft);font-size:12.5px}.billing-muted{color:var(--faint);font-size:13px;margin:.9rem 0 0}.billing-plan-section{margin-top:2.6rem}.billing-main-action{margin-bottom:1.25rem}.billing-main-action form+form{margin-top:.7rem}.billing-plans{display:grid;grid-template-columns:repeat(3,1fr);gap:1.2rem}.billing-plan{background:var(--card);border:1px solid var(--rule);border-radius:16px;padding:1.6rem 1.45rem;display:flex;flex-direction:column;position:relative}.billing-plan.billing-current{background:var(--mist);border-color:#cfe6cb}.billing-featured{border:2px solid var(--green);box-shadow:0 20px 40px -28px rgb(15 90 12 / .35)}.billing-ribbon{position:absolute;top:-.8rem;left:1.5rem;background:var(--green);color:#fff;padding:.3rem .75rem;border-radius:99px;font-size:11px;font-weight:700}.billing-plan-name{font-size:13px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:var(--soft);margin-bottom:.8rem}.billing-current .billing-plan-name{color:var(--deep)}.billing-price{font-size:36px;font-weight:800;line-height:1.1}.billing-price small{font-size:14px;font-weight:500;color:var(--soft)}.billing-sub{font-size:13px;color:var(--faint);min-height:2.6rem;margin:.35rem 0 1.2rem}.billing-sub b{color:var(--deep)}.billing-current-badge{display:inline-flex;align-items:center;gap:.35rem;color:var(--deep);font-size:12px;font-weight:650;margin:0 0 1.2rem}.billing-current-badge svg{width:13px;height:13px}.billing-includes{font-size:12.5px;color:var(--faint);font-weight:650;margin-bottom:.7rem}.billing-features{list-style:none;padding:0;margin:0 0 1.3rem;display:flex;flex-direction:column;gap:.55rem;flex:1}.billing-features li{display:flex;align-items:flex-start;gap:.45rem;font-size:14px}.billing-features svg{width:16px;height:16px;color:var(--green);flex:none;margin-top:2px}.billing-plan-foot{color:var(--faint);font-size:13px;margin-top:auto}.billing-plan-foot svg{width:14px;height:14px;vertical-align:-2px;color:var(--deep)}.billing-btn{display:block;width:100%;border:1px solid var(--rule);border-radius:9px;padding:.7rem 1rem;background:#fff;color:var(--ink);font:inherit;font-weight:650;cursor:pointer}.billing-btn:hover{border-color:var(--green);background:var(--mist);color:var(--deep)}.billing-btn:focus-visible{outline:3px solid var(--green);outline-offset:2px}.billing-btn-dark{background:var(--ink);border-color:var(--ink);color:#fff}.billing-btn-green{background:var(--green);border-color:var(--green);color:#fff}.billing-btn-solid{background:var(--ink);border-color:var(--ink);color:#fff}.billing-btn-crypto{background:#f3eee3;border-color:#c8b88e}.crypto-option{margin-top:1rem;padding:1rem 1.2rem;border:1px solid #d8cfba;border-radius:12px;background:#fbf8f0;display:flex;align-items:center;justify-content:space-between;gap:1rem}.crypto-option-copy{display:flex;align-items:center;gap:.8rem;flex-wrap:wrap}.crypto-option-copy strong{font-size:14px}.crypto-option-copy>span{font-size:13px;color:var(--soft)}.crypto-assets{display:flex;gap:.35rem}.crypto-assets span{width:1.7rem;height:1.7rem;border-radius:50%;display:grid;place-items:center;background:#efe6d2;color:#6d5524;font-size:.8rem;font-weight:750}.crypto-option-active{color:var(--deep);background:var(--mist);border-color:#cfe6cb;font-size:13px}.crypto-option-active svg{width:15px;height:15px;vertical-align:-3px}.crypto-option-muted{color:var(--faint);font-size:13px}.billing-footnote{color:var(--faint);font-size:13px;margin-top:1.8rem}.billing-footnote a{color:var(--deep);font-weight:650}@media(max-width:1050px){.billing-plans{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){body{padding:2.5rem 1rem}.billing-h1{font-size:25px}.billing-usage{padding:1.2rem}.billing-plan{padding:1.35rem}.billing-plans{grid-template-columns:1fr}.crypto-option{align-items:flex-start;flex-direction:column}}
  </style></head><body><main class="billing-wrap"><a class="billing-crumb" href="/admin">← blognice admin</a><h1 class="billing-h1">Billing</h1><p class="billing-account">Account: <b>${esc(account.email)}</b></p>${statusNotice}${unknownPaid}${usage}<section class="billing-section billing-plan-section"><div class="billing-section-head"><h2>Plan</h2>${active && renewal ? `<span>${esc(renewal)}</span>` : cryptoActive ? `<span>Valid through ${esc(cryptoExpiry)}</span>` : ""}</div><p class="billing-notice billing-founder-note"><strong>Founding member pricing</strong><br>Join Blognice while we're still building and help shape what comes next. <b>$36/year or $5/month.</b> Founding members keep their selected price for as long as that subscription remains continuously active. We plan to close founding pricing after the first 1,000 paying members. <strong>Planned standard pricing:</strong> $119/year or $12.99/month.</p>${billingAction ? `<div class="billing-main-action">${billingAction}</div>` : ""}<div class="billing-plans">${freeCard}${monthlyCard}${yearlyCard}</div>${cryptoOption}</section>${referralCode}<p class="billing-footnote">Stripe remains the primary payment provider. Payment details, receipts, invoices, cancellations, and plan changes are managed securely in Stripe. Crypto payments are annual-only, prepaid, and handled by NOWPayments; there is no automatic renewal. ${active ? "" : "Upgrade when you’re ready; access starts only after the payment provider confirms payment."}</p>${formerCustomer}</main></body></html>`;
}

type AffiliateTermsConfig = {
  termsVersion: string;
  termsDocumentDigest: string;
  policyVersion: string;
  termsUrl: string;
  couponId: string;
};

function affiliateTermsConfig(env: Bindings): AffiliateTermsConfig | null {
  const termsVersion = String(env.AFFILIATE_TERMS_VERSION || "").trim();
  const termsDocumentDigest = String(env.AFFILIATE_TERMS_DOCUMENT_DIGEST || "").trim();
  const policyVersion = String(env.AFFILIATE_POLICY_VERSION || "").trim();
  const termsUrl = String(env.AFFILIATE_TERMS_URL || "").trim();
  const couponId = String(env.STRIPE_AFFILIATE_COUPON_ID || "").trim();
  if (!termsVersion || !termsDocumentDigest || !policyVersion || !termsUrl || !couponId) return null;
  try {
    if (new URL(termsUrl).protocol !== "https:") return null;
  } catch {
    return null;
  }
  return { termsVersion, termsDocumentDigest, policyVersion, termsUrl, couponId };
}

function affiliatePerformanceChart(series: AffiliateFunnelDay[] | null): string {
  if (!series) return `<section class="affiliate-card"><h2>Clicks and sales</h2><p class="affiliate-card-copy">Last 90 days</p><p class="affiliate-chart-empty">Analytics are temporarily unavailable. Your exact sales and commission totals above are unaffected.</p></section>`;
  const width = 900, height = 260, left = 44, right = 16, top = 18, bottom = 34;
  const plotWidth = width - left - right, plotHeight = height - top - bottom;
  const peak = Math.max(1, ...series.flatMap((day) => [day.clicks, day.sales]));
  const x = (index: number) => left + (series.length <= 1 ? 0 : index * plotWidth / (series.length - 1));
  const y = (value: number) => top + plotHeight - value * plotHeight / peak;
  const points = (key: "clicks" | "sales") => series.map((day, index) => `${x(index).toFixed(1)},${y(day[key]).toFixed(1)}`).join(" ");
  const grid = [0, .25, .5, .75, 1].map((ratio) => {
    const gridY = top + plotHeight - ratio * plotHeight;
    return `<line x1="${left}" y1="${gridY}" x2="${width - right}" y2="${gridY}"/><text x="${left - 8}" y="${gridY + 4}" text-anchor="end">${Math.round(peak * ratio)}</text>`;
  }).join("");
  const labelIndexes = [...new Set([0, Math.floor((series.length - 1) / 2), series.length - 1])];
  const dateLabels = labelIndexes.map((index) => `<text x="${x(index)}" y="${height - 8}" text-anchor="${index === 0 ? "start" : index === series.length - 1 ? "end" : "middle"}">${esc(series[index]?.date || "")}</text>`).join("");
  const clickTotal = series.reduce((sum, day) => sum + day.clicks, 0);
  const saleTotal = series.reduce((sum, day) => sum + day.sales, 0);
  const range = series.length ? `${series[0].date} through ${series[series.length - 1].date}` : "the last 90 days";
  return `<section class="affiliate-card"><div class="affiliate-chart-head"><div><h2>Clicks and sales</h2><p class="affiliate-card-copy">Last 90 days · approximate, consent-aware analytics</p></div><div class="affiliate-chart-legend" aria-hidden="true"><span class="clicks">Clicks ${clickTotal}</span><span class="sales">Sales ${saleTotal}</span></div></div><div class="affiliate-chart-wrap"><svg class="affiliate-chart" viewBox="0 0 ${width} ${height}" role="img" aria-labelledby="affiliate-chart-title affiliate-chart-desc"><title id="affiliate-chart-title">Referral clicks and sales over 90 days</title><desc id="affiliate-chart-desc">${clickTotal} link clicks and ${saleTotal} sales from ${esc(range)}.</desc><g class="affiliate-chart-grid">${grid}${dateLabels}</g><polyline class="affiliate-chart-line clicks" points="${points("clicks")}"/><polyline class="affiliate-chart-line sales" points="${points("sales")}"/></svg></div><p class="affiliate-help">Clicks can be lower than actual traffic where analytics consent is required or tracking is blocked. Sales are provider-confirmed conversion events.</p></section>`;
}

function affiliateDashboardPage(account: Account, dashboard: AffiliateDashboard | null, rootDomain: string, terms: AffiliateTermsConfig | null, message = "", performance: AffiliateFunnelDay[] | null = null): string {
  const styles = `<style>
    .affiliate-page{max-width:1040px}.affiliate-head{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem}.affiliate-head h1{margin:0 0 .3rem}.affiliate-eyebrow{color:var(--muted);margin:0}.affiliate-status{display:inline-flex;align-items:center;min-height:2rem;padding:.35rem .7rem;border-radius:999px;background:color-mix(in srgb,var(--accent) 12%,transparent);color:var(--accent);font-size:.8rem;font-weight:750}.affiliate-card{background:var(--panel);border:1px solid var(--rule);border-radius:14px;padding:1.4rem;margin:0 0 1rem}.affiliate-card h2{font-size:1.1rem;margin:0 0 .35rem}.affiliate-card-copy{color:var(--muted);margin:.2rem 0 1rem}.affiliate-alert{border:1px solid #e8c58c;background:#fff8e8;border-radius:12px;padding:1rem 1.1rem;margin-bottom:1rem}.affiliate-alert h2{font-size:1rem;margin:0 0 .3rem}.affiliate-alert p{margin:.2rem 0 .8rem}.affiliate-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.affiliate-enrollment-layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(19rem,.85fr);gap:1.25rem;align-items:start}.affiliate-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.75rem;margin-top:1.2rem}.affiliate-fact,.affiliate-kpi{border:1px solid var(--rule);border-radius:11px;padding:1rem;background:var(--bg)}.affiliate-fact strong,.affiliate-kpi strong{display:block;font-size:1.45rem;line-height:1.15}.affiliate-fact span,.affiliate-kpi span{display:block;color:var(--muted);font-size:.82rem;margin-top:.25rem}.affiliate-form{display:grid;gap:.8rem}.affiliate-form label{font-weight:650}.affiliate-form input[type=text],.affiliate-form select,.affiliate-referral-input{width:100%;min-height:44px;border:1px solid var(--rule);border-radius:9px;background:var(--field);color:var(--ink);padding:.7rem .8rem;font:inherit}.affiliate-check{display:grid;grid-template-columns:auto 1fr;gap:.65rem;align-items:start;font-weight:400!important}.affiliate-check input{width:1.1rem;height:1.1rem;margin-top:.2rem}.affiliate-btn{min-height:44px;border:1px solid var(--accent);border-radius:9px;padding:.65rem 1rem;background:var(--accent);color:var(--accent-ink);font:inherit;font-weight:700;cursor:pointer}.affiliate-btn.secondary{background:var(--panel);color:var(--accent)}.affiliate-referral-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:.6rem}.affiliate-referral-input{font-family:var(--mono);overflow:hidden;text-overflow:ellipsis}.affiliate-code{display:inline-flex;padding:.3rem .55rem;border-radius:6px;background:var(--bg);font:700 .9rem var(--mono)}.affiliate-kpi-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.75rem}.affiliate-kpi.primary{background:color-mix(in srgb,var(--accent) 9%,var(--panel));border-color:color-mix(in srgb,var(--accent) 30%,var(--rule))}.affiliate-kpi.primary strong{color:var(--accent)}.affiliate-chart-head{display:flex;align-items:flex-start;justify-content:space-between;gap:1rem}.affiliate-chart-legend{display:flex;gap:1rem;flex-wrap:wrap;font-size:.82rem;font-weight:700}.affiliate-chart-legend span:before{content:"";display:inline-block;width:.75rem;height:.18rem;border-radius:99px;margin-right:.35rem;vertical-align:.2rem}.affiliate-chart-legend .clicks:before{background:var(--accent)}.affiliate-chart-legend .sales:before{background:#b45309}.affiliate-chart-wrap{overflow-x:auto}.affiliate-chart{display:block;width:100%;min-width:38rem;height:auto}.affiliate-chart-grid line{stroke:var(--rule);stroke-width:1}.affiliate-chart-grid text{fill:var(--muted);font:11px system-ui,sans-serif}.affiliate-chart-line{fill:none;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}.affiliate-chart-line.clicks{stroke:var(--accent)}.affiliate-chart-line.sales{stroke:#b45309}.affiliate-chart-empty{color:var(--muted);padding:2rem 0}.affiliate-table-wrap{overflow-x:auto}.affiliate-table{width:100%;min-width:34rem}.affiliate-table th{color:var(--muted);font-size:.75rem;text-transform:uppercase;letter-spacing:.04em}.affiliate-empty{text-align:center;padding:2rem!important;color:var(--muted)}.affiliate-badge{display:inline-flex;padding:.22rem .55rem;border-radius:999px;background:var(--bg);font-size:.78rem;font-weight:700}.affiliate-help{color:var(--muted);font-size:.85rem}.affiliate-copy-status{min-height:1.2rem;color:var(--accent);font-size:.82rem;margin:.45rem 0 0}
    @media(max-width:800px){.affiliate-kpi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.affiliate-enrollment-layout,.affiliate-grid{grid-template-columns:1fr}}
    @media(max-width:520px){.affiliate-head{display:block}.affiliate-status{margin-top:.7rem}.affiliate-facts,.affiliate-kpi-grid{grid-template-columns:1fr}.affiliate-referral-row{grid-template-columns:1fr}.affiliate-btn{width:100%}.affiliate-card{padding:1.1rem}}
    @media(prefers-color-scheme:dark){.affiliate-alert{background:#2a2415;border-color:#66572c}}
  </style>`;
  if (!dashboard) {
    const notice = message ? `<div class="affiliate-alert" role="alert">${esc(message)}</div>` : "";
    const enrollment = terms
      ? `<form class="affiliate-card affiliate-form" method="post" action="/admin/affiliate/enroll"><h2>Create your referral code</h2><p class="affiliate-card-copy">Choose the code readers will see in your referral link. It must be unique.</p><label for="referral-code">Referral code</label><input type="text" id="referral-code" name="referral_code" required minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9-]{2,31}" autocomplete="off" aria-describedby="referral-code-help"><span class="affiliate-help" id="referral-code-help">3–32 letters, numbers, or hyphens.</span><label class="affiliate-check"><input type="checkbox" name="accept_terms" value="yes" required><span>I agree to the <a href="${esc(terms.termsUrl)}" target="_blank" rel="noopener noreferrer">Affiliate Terms</a> (${esc(terms.termsVersion)}).</span></label><button class="affiliate-btn" type="submit">Enable affiliate program</button></form>`
      : `<p>Affiliate enrollment will open after the Affiliate Terms are published and approved.</p>`;
    return shell("Affiliate program — blognice", `${styles}<main class="page affiliate-page"><div class="affiliate-head"><div><h1>Affiliate program</h1><p class="affiliate-eyebrow">Recommend Blognice and earn from qualifying subscriptions.</p></div><a href="${esc(terms?.termsUrl || "/affiliate-terms")}">Affiliate Terms</a></div>${notice}<div class="affiliate-enrollment-layout"><section class="affiliate-card"><h2>Share something worth writing on</h2><p>Earn <strong>50% commission</strong> on qualifying referred revenue. Your readers receive 10% off their first 12 paid service months.</p><div class="affiliate-facts"><div class="affiliate-fact"><strong>50%</strong><span>commission</span></div><div class="affiliate-fact"><strong>10%</strong><span>reader discount</span></div><div class="affiliate-fact"><strong>60 days</strong><span>commission maturation</span></div><div class="affiliate-fact"><strong>US$100</strong><span>payout threshold</span></div></div><p class="affiliate-help">Available to eligible Affiliates in the United States, Canada, the United Kingdom, and Thailand.</p></section>${enrollment}</div></main>`, account);
  }
  const money = (minor: number) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(minor / 100);
  const referralUrl = `https://www.${rootDomain}/?ref=${encodeURIComponent(dashboard.referralCode)}`;
  const termsAction = dashboard.status === "terms_required" && terms
    ? `<section class="affiliate-alert" role="alert"><h2>Updated Affiliate Terms</h2><p>Attribution and payouts are paused until you accept the current terms.</p><form class="affiliate-form" method="post" action="/admin/affiliate/accept-terms"><label class="affiliate-check"><input type="checkbox" name="accept_terms" value="yes" required><span>I agree to the <a href="${esc(terms.termsUrl)}" target="_blank" rel="noopener noreferrer">Affiliate Terms</a> (${esc(terms.termsVersion)}).</span></label><button class="affiliate-btn" type="submit">Accept updated terms</button></form></section>`
    : "";
  const discountSetup = dashboard.stripePromotionCodeReady
    ? `<p><strong>Your referral discount is active.</strong></p>`
    : `<p><strong>Your referral link is not active yet.</strong> Finish Stripe discount setup before sharing it.</p><form method="post" action="/admin/affiliate/promotion"><button class="affiliate-btn secondary" type="submit">Retry discount setup</button></form>`;
  const connect = dashboard.status === "terms_required"
    ? `<p>Payout setup is paused until the updated Affiliate Terms are accepted.</p>`
    : dashboard.stripeConnectStatus === "ready"
    ? `<p><strong>Stripe payouts are ready.</strong>${dashboard.stripeConnectCountry ? ` Payout country: ${esc(dashboard.stripeConnectCountry)}.` : ""}</p>`
    : dashboard.stripeConnectStatus === "not_started"
      ? `<form class="affiliate-form" method="post" action="/admin/affiliate/connect"><label for="payout-country">Payout country</label><select id="payout-country" name="country" required autocomplete="country"><option value="">Choose a country</option><option value="US">United States</option><option value="CA">Canada</option><option value="GB">United Kingdom</option><option value="TH">Thailand</option></select><button class="affiliate-btn" type="submit">Set up Stripe payouts</button></form><p class="affiliate-help">Stripe hosts identity verification and bank-account collection. Blognice does not store your bank details.</p>`
      : `<form method="post" action="/admin/affiliate/connect"><button class="affiliate-btn secondary" type="submit">${dashboard.stripeConnectStatus === "restricted" ? "Resolve Stripe payout requirements" : "Continue Stripe payout setup"}</button></form>`;
  const humanStatus: Record<string, string> = { active: "Active", terms_required: "Action required", suspended: "Suspended", closed: "Closed", prepared: "Ready", reconciliation: "Under review", paid: "Paid", cancelled: "Cancelled" };
  const payoutRows = dashboard.payouts.map((payout) => `<tr><td>${new Date(payout.createdAt * 1000).toISOString().slice(0, 10)}</td><td>${esc(money(payout.amountMinor))}</td><td><span class="affiliate-badge">${esc(humanStatus[payout.status] || payout.status)}</span></td></tr>`).join("");
  const copyScript = `<script>(function(){var button=document.getElementById('copy-referral-link'),input=document.getElementById('affiliate-referral-link'),status=document.getElementById('copy-referral-status');if(!button||!input||!status)return;button.addEventListener('click',async function(){try{await navigator.clipboard.writeText(input.value);status.textContent='Referral link copied.';button.textContent='Copied';}catch(_){input.select();status.textContent='Select and copy the link.';}});})();</script>`;
  return shell("Affiliate dashboard — blognice", `${styles}<main class="page affiliate-page"><div class="affiliate-head"><div><h1>Affiliate program</h1><p class="affiliate-eyebrow">Your referrals, commission, and payouts in one place.</p></div><span class="affiliate-status">${esc(humanStatus[dashboard.status] || dashboard.status)}</span></div>${termsAction}<section class="affiliate-card"><h2>Your referral link</h2><p class="affiliate-card-copy">Readers receive 10% off their first 12 paid service months.</p><p>Referral code <span class="affiliate-code">${esc(dashboard.referralCode)}</span></p><div class="affiliate-referral-row"><input class="affiliate-referral-input" id="affiliate-referral-link" type="text" readonly value="${esc(referralUrl)}" aria-label="Referral link"><button class="affiliate-btn" id="copy-referral-link" type="button">Copy link</button></div><p class="affiliate-copy-status" id="copy-referral-status" aria-live="polite"></p>${discountSetup}</section><section class="affiliate-card"><h2>Performance</h2><p class="affiliate-card-copy">Commission matures after 60 days. Payouts are prepared monthly from US$100.</p><div class="affiliate-kpi-grid"><div class="affiliate-kpi primary"><strong>${esc(money(dashboard.availableCommissionMinor))}</strong><span>Available for payout</span></div><div class="affiliate-kpi"><strong>${esc(money(dashboard.pendingCommissionMinor))}</strong><span>Pending maturation</span></div><div class="affiliate-kpi"><strong>${esc(money(dashboard.netCommissionMinor))}</strong><span>Net commission</span></div><div class="affiliate-kpi"><strong>${esc(money(dashboard.paidPayoutMinor))}</strong><span>Paid</span></div><div class="affiliate-kpi"><strong>${dashboard.attributionCount}</strong><span>Attributed accounts</span></div><div class="affiliate-kpi"><strong>${dashboard.conversionCount}</strong><span>Converted accounts</span></div><div class="affiliate-kpi"><strong>${esc(money(dashboard.openReserveMinor))}</strong><span>Reserved</span></div></div></section>${affiliatePerformanceChart(performance)}<div class="affiliate-grid"><section class="affiliate-card"><h2>Stripe payouts</h2><p class="affiliate-card-copy">Complete payout setup before your first payout is ready.</p>${connect}</section><section class="affiliate-card"><h2>Payout policy</h2><p>Available commission is paid monthly after it reaches US$100. Refunds, credits, and disputes can adjust the balance.</p><a href="${esc(terms?.termsUrl || "/affiliate-terms")}">Read Affiliate Terms</a></section></div><section class="affiliate-card"><h2>Payout history</h2><div class="affiliate-table-wrap"><table class="affiliate-table" aria-label="Affiliate payout history"><thead><tr><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody>${payoutRows || `<tr><td class="affiliate-empty" colspan="3">No payouts yet. Your first payout will appear here after your available balance reaches US$100.</td></tr>`}</tbody></table></div></section></main>${copyScript}`, account);
}

app.get("/admin/affiliate", async (c) => {
  const account = await currentAccount(c);
  if (!account) return c.redirect("/admin/login");
  if (isSuspended(account)) return suspendedResponse(c, account);
  const terms = affiliateTermsConfig(c.env);
  if (terms) {
    const review = await requireCurrentAffiliateTermsInDb(c.env.DB, { accountId: account.id, termsVersion: terms.termsVersion, policyVersion: terms.policyVersion, requiredAt: Math.floor(Date.now() / 1000) });
    if (review.required && c.env.EMAIL_QUEUE) c.executionCtx.waitUntil(relayAffiliateEmailOutboxInDb(c.env.DB, c.env.EMAIL_QUEUE));
  }
  const dashboard = await getAffiliateDashboardInDb(c.env.DB, account.id, Math.floor(Date.now() / 1000));
  let performance: AffiliateFunnelDay[] | null = null;
  if (dashboard && metricsConfigured(c.env)) {
    try {
      performance = await affiliateFunnelSeries(c.env, account.id, 90);
    } catch (error) {
      console.error(JSON.stringify({ message: "Affiliate analytics query failed", accountId: account.id, error: error instanceof Error ? error.message.slice(0, 300) : "Unknown analytics error" }));
    }
  }
  return c.html(affiliateDashboardPage(account, dashboard, c.env.ROOT_DOMAIN, terms, String(c.req.query("message") || "").slice(0, 200), performance));
});

app.post("/admin/affiliate/accept-terms", async (c) => {
  const account = await currentAccount(c);
  if (!account) return c.redirect("/admin/login");
  if (isSuspended(account)) return suspendedResponse(c, account);
  if (!isEmailVerified(account)) return c.redirect("/admin/affiliate?message=Verify+your+email+before+accepting+terms", 303);
  const requestOrigin = c.req.header("Origin");
  if (!requestOrigin || requestOrigin !== new URL(c.req.url).origin) return c.json({ error: "same-origin request required" }, 403);
  const terms = affiliateTermsConfig(c.env);
  if (!terms) return c.json({ error: "affiliate terms are not configured" }, 503);
  const form = await c.req.formData();
  if (String(form.get("accept_terms") || "") !== "yes") return c.redirect("/admin/affiliate?message=You+must+accept+the+Affiliate+Terms", 303);
  const result = await reacceptAffiliateTermsInDb(c.env.DB, {
    accountId: account.id, termsVersion: terms.termsVersion,
    termsDocumentDigest: terms.termsDocumentDigest, policyVersion: terms.policyVersion,
    acceptedAt: Math.floor(Date.now() / 1000),
  });
  if (!result.accepted) return c.redirect("/admin/affiliate?message=Updated+terms+were+not+required", 303);
  return c.redirect("/admin/affiliate", 303);
});

app.post("/admin/affiliate/enroll", async (c) => {
  const account = await currentAccount(c);
  if (!account) return c.redirect("/admin/login");
  if (isSuspended(account)) return suspendedResponse(c, account);
  if (!isEmailVerified(account)) return c.redirect("/admin/affiliate?message=Verify+your+email+before+enrolling", 303);
  const requestOrigin = c.req.header("Origin");
  if (!requestOrigin || requestOrigin !== new URL(c.req.url).origin) return c.json({ error: "same-origin request required" }, 403);
  const terms = affiliateTermsConfig(c.env);
  if (!terms) return c.json({ error: "affiliate enrollment is not configured" }, 503);
  const existing = await c.env.DB.prepare("SELECT stripe_promotion_code_id FROM affiliate_profiles WHERE account_id = ?").bind(account.id).first<{ stripe_promotion_code_id: string | null }>();
  if (existing) return c.redirect("/admin/affiliate", 303);
  const form = await c.req.formData();
  if (String(form.get("accept_terms") || "") !== "yes") {
    return c.redirect("/admin/affiliate?message=You+must+accept+the+Affiliate+Terms", 303);
  }
  const referralCode = String(form.get("referral_code") || "").trim();
  if (!/^[A-Za-z0-9][A-Za-z0-9-]{2,31}$/.test(referralCode)) {
    return c.redirect("/admin/affiliate?message=Choose+a+valid+referral+code", 303);
  }
  try {
    await enableAffiliateProfileInDb(c.env.DB, {
      accountId: account.id,
      referralCode,
      termsVersion: terms.termsVersion,
      termsDocumentDigest: terms.termsDocumentDigest,
      policyVersion: terms.policyVersion,
      acceptedAt: Math.floor(Date.now() / 1000),
    });
  } catch {
    return c.redirect("/admin/affiliate?message=That+referral+code+is+unavailable", 303);
  }
  try {
    const promotion = await createAffiliatePromotionCode(c.env, {
      couponId: terms.couponId,
      referralCode,
      affiliateAccountId: account.id,
    });
    const attached = await attachStripePromotionCodeInDb(c.env.DB, {
      accountId: account.id,
      promotionCodeId: promotion.promotionCodeId,
    });
    if (!attached.attached) throw new Error("Affiliate promotion code was not attached.");
  } catch {
    return c.redirect("/admin/affiliate?message=Discount+setup+is+pending.+Please+retry", 303);
  }
  await enqueueAffiliateEnrollmentEmailInDb(c.env.DB, account.id, Math.floor(Date.now() / 1000));
  if (c.env.EMAIL_QUEUE) c.executionCtx.waitUntil(relayAffiliateEmailOutboxInDb(c.env.DB, c.env.EMAIL_QUEUE));
  return c.redirect("/admin/affiliate", 303);
});

