app.post("/admin/billing/checkout", async (c) => {
  const account = await currentAccount(c);
  if (!account) return c.redirect("/admin/login");
  if (isSuspended(account)) return suspendedResponse(c, account);
  if (!stripeConfigured(c.env)) return c.redirect("/admin/billing?message=Stripe is not configured yet.");
  const form = await c.req.formData();
  const plan = String(form.get("plan") || "monthly");
  const priceId = plan === "yearly" ? (c.env.STRIPE_YEARLY_PRICE_ID || "") : (c.env.STRIPE_MONTHLY_PRICE_ID || c.env.STRIPE_PRICE_ID || "");
  if (!priceId) return c.redirect("/admin/billing?message=The selected Stripe plan is not configured yet.");
  let billing: any;
  try {
    billing = await c.env.DB.prepare("SELECT stripe_customer_id, billing_status, vip_granted_at, vip_expires_at FROM accounts WHERE id = ?").bind(account.id).first<{ stripe_customer_id?: string | null; billing_status: string; vip_granted_at?: number | null; vip_expires_at?: number | null }>();
  } catch {
    billing = await c.env.DB.prepare("SELECT stripe_customer_id, billing_status FROM accounts WHERE id = ?").bind(account.id).first<{ stripe_customer_id?: string | null; billing_status: string }>();
  }
  if (billing && (["active", "trialing", "past_due"].includes(billing.billing_status) || (Number((billing as any).vip_granted_at || 0) > 0 && ((billing as any).vip_expires_at == null || Number((billing as any).vip_expires_at) > Math.floor(Date.now()/1000))))) return c.redirect("/admin/billing?message=This account already has a subscription.");
  try {
    const origin = new URL(c.req.url).origin;
    const now = Math.floor(Date.now() / 1000);
    const { attribution } = await beginCheckoutAttributionInDb(c.env.DB, account.id, now);
    const experimentContext = await loadFunnelExperimentCheckoutContextInDb(c.env.DB, account.id);
    if (attribution && !attribution.stripePromotionCodeId) throw new Error("The affiliate discount is not configured yet.");
    const affiliateCheckout = attribution ? await createStripeCheckoutInDb(c.env.DB, {
      accountId: account.id,
      attributionId: attribution.attributionId,
      cadence: plan === "yearly" ? "annual" : "monthly",
      priceId,
      promotionCodeId: attribution.stripePromotionCodeId!,
      policyVersion: attribution.policyVersion,
      discountRateNumerator: 1,
      discountRateDenominator: 10,
      commissionRateNumerator: 1,
      commissionRateDenominator: 2,
      createdAt: now,
      expiresAt: now + 30 * 60,
      experimentKey: experimentContext?.experimentKey,
      experimentVariant: experimentContext?.variant,
    }) : null;
    const session = await createCheckoutSession(c.env, {
      accountId: account.id,
      email: account.email,
      priceId,
      customerId: billing?.stripe_customer_id,
      affiliateCheckoutId: affiliateCheckout?.checkoutId,
      promotionCodeId: affiliateCheckout?.promotionCodeId,
      experimentKey: experimentContext?.experimentKey,
      experimentVariant: experimentContext?.variant,
      successUrl: `${origin}/admin/billing?message=Checkout completed. Subscription access will update after Stripe confirms payment.`,
      cancelUrl: `${origin}/admin/billing?message=Checkout cancelled.`,
    });
    if (affiliateCheckout) {
      await c.env.DB.prepare(
        "UPDATE affiliate_stripe_checkouts SET status = 'created', stripe_session_id = ? WHERE id = ? AND status = 'pending'",
      ).bind(session.id, affiliateCheckout.checkoutId).run();
    }
    await recordFunnelExperimentCheckoutInDb(c.env.DB, account.id, now).catch((error) => console.error(JSON.stringify({ message: "Funnel Experiment checkout milestone failed", accountId: account.id, error: error instanceof Error ? error.message : String(error) })));
    await recordExperimentCheckoutStart(c, account.id);
    return c.redirect(session.url, 303);
  } catch (error) {
    return c.redirect(`/admin/billing?message=${encodeURIComponent(error instanceof Error ? error.message : "Stripe checkout failed.")}`);
  }
});

