app.post("/admin/billing/crypto/checkout", async (c) => {
  const account = await currentAccount(c);
  if (!account) return c.redirect("/admin/login");
  if (isSuspended(account)) return suspendedResponse(c, account);
  if (!nowPaymentsConfigured(c.env)) return c.redirect("/admin/billing?message=Crypto payments are not configured yet.");
  let billing: any;
  try {
    billing = await c.env.DB.prepare("SELECT billing_status, crypto_paid_through, vip_granted_at, vip_expires_at FROM accounts WHERE id = ?").bind(account.id).first<{ billing_status: string; crypto_paid_through?: number | null; vip_granted_at?: number | null; vip_expires_at?: number | null }>();
  } catch {
    billing = await c.env.DB.prepare("SELECT billing_status, crypto_paid_through FROM accounts WHERE id = ?").bind(account.id).first<{ billing_status: string; crypto_paid_through?: number | null }>();
  }
  if (accountHasPaidPlan(billing || {})) return c.redirect("/admin/billing?message=This account already has paid access.");
  try {
    const origin = new URL(c.req.url).origin;
    const now = Math.floor(Date.now() / 1000);
    const { attribution } = await beginCheckoutAttributionInDb(c.env.DB, account.id, now);
    const experimentContext = await loadFunnelExperimentCheckoutContextInDb(c.env.DB, account.id);
    const expectedDiscountedAmountMinor = affiliateAnnualPriceMinor(Boolean(attribution), NOWPAYMENTS_ANNUAL_USD * 100);
    const checkout = await createNowPaymentsCheckoutInDb(c.env.DB, {
      accountId: account.id,
      attributionId: attribution?.attributionId ?? null,
      expectedDiscountedAmountMinor,
      policyVersion: attribution?.policyVersion ?? "none",
      discountRateNumerator: attribution ? 1 : 0,
      discountRateDenominator: 10,
      commissionRateNumerator: attribution ? 1 : 0,
      commissionRateDenominator: 2,
      createdAt: now,
      expiresAt: now + 15 * 60,
      experimentKey: experimentContext?.experimentKey,
      experimentVariant: experimentContext?.variant,
    });
    const invoice = await createAnnualInvoice(c.env, {
      orderId: checkout.orderId,
      experimentKey: experimentContext?.experimentKey,
      experimentVariant: experimentContext?.variant,
      priceUsdMinor: checkout.expectedDiscountedAmountMinor,
      callbackUrl: `${origin}/nowpayments/webhook`,
      successUrl: `${origin}/admin/billing?message=Crypto payment received. Access will update after NOWPayments confirms it.`,
      cancelUrl: `${origin}/admin/billing?message=Crypto payment cancelled.`,
    });
    const url = invoice.invoice_url || invoice.payment_url || invoice.pay_url;
    if (!url) throw new Error("NOWPayments did not return an invoice URL.");
    await c.env.DB.prepare(
      "UPDATE affiliate_nowpayments_checkouts SET status = 'invoiced', provider_invoice_id = ? WHERE order_id = ? AND status = 'pending'",
    ).bind(String(invoice.id), checkout.orderId).run();
    await recordFunnelExperimentCheckoutInDb(c.env.DB, account.id, now).catch((error) => console.error(JSON.stringify({ message: "Funnel Experiment checkout milestone failed", accountId: account.id, error: error instanceof Error ? error.message : String(error) })));
    await recordExperimentCheckoutStart(c, account.id);
    return c.redirect(url, 303);
  } catch (error) {
    return c.redirect(`/admin/billing?message=${encodeURIComponent(error instanceof Error ? error.message : "Crypto checkout failed.")}`);
  }
});

app.post("/nowpayments/webhook", async (c) => {
  const raw = await c.req.text();
  if (!await verifyNowPaymentsIpn(raw, c.req.header("x-nowpayments-sig"), c.env.NOWPAYMENTS_IPN_SECRET)) return c.json({ error: "invalid signature" }, 400);
  let payload: any;
  try { payload = JSON.parse(raw); } catch { return c.json({ error: "invalid payload" }, 400); }
  const paymentId = String(payload.payment_id || "");
  const orderId = String(payload.order_id || "");
  if (!paymentId || !orderId) return c.json({ error: "missing payment identity" }, 400);
  try {
    const payment = await getPayment(c.env, paymentId);
    if (String(payment.order_id || orderId) !== orderId) throw new Error("NOWPayments order mismatch.");
    const checkout = await c.env.DB.prepare(
      "SELECT account_id, expected_discounted_amount_minor FROM affiliate_nowpayments_checkouts WHERE order_id = ?",
    ).bind(orderId).first<{ account_id: number; expected_discounted_amount_minor: number }>();
    if (!checkout) throw new Error("NOWPayments order could not be mapped to a durable checkout.");
    if (Math.round(Number(payment.price_amount) * 100) !== checkout.expected_discounted_amount_minor || String(payment.price_currency || "").toLowerCase() !== "usd") throw new Error("NOWPayments payment amount mismatch.");
    const accountId = checkout.account_id;
    const now = Math.floor(Date.now() / 1000);
    const paymentStatus = String(payment.payment_status || payload.payment_status || "");
    const finished = isTerminalPaidStatus(paymentStatus) && isNowPaymentsAmountFullyPaid(payment);
    // Unpaid/intermediate states must remain retryable: NOWPayments can send a
    // later finished callback. Only a true post-credit refund revokes access.
    const reversible = paymentStatus === "refunded";
    await c.env.DB.prepare(
      `INSERT INTO crypto_payments (id, account_id, order_id, plan, price_usd_cents, pay_currency, pay_amount, actually_paid, status, created_at, updated_at, paid_at, credited_at)
       VALUES (?, ?, ?, 'yearly', ?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(order_id) DO UPDATE SET pay_currency = excluded.pay_currency, pay_amount = excluded.pay_amount, actually_paid = excluded.actually_paid, status = excluded.status, updated_at = excluded.updated_at, paid_at = COALESCE(crypto_payments.paid_at, excluded.paid_at), credited_at = COALESCE(crypto_payments.credited_at, excluded.credited_at)`
    ).bind(paymentId, accountId, orderId, checkout.expected_discounted_amount_minor, payment.pay_currency || payload.pay_currency || null, payment.pay_amount || payload.pay_amount || null, payment.actually_paid || payload.actually_paid || null, paymentStatus, now, now, finished ? now : null, null).run();
    if (finished) {
      const settlement = await settleNowPaymentsCheckoutInDb(c.env.DB, {
        orderId,
        paymentId,
        paidAt: now,
        entitlementSeconds: NOWPAYMENTS_ANNUAL_SECONDS,
        maturationSeconds: 60 * 24 * 60 * 60,
      });
      if (settlement.settled) await recordAffiliateConversion(c, accountId, "nowpayments");
      await recordFunnelExperimentConversionInDb(c.env.DB, {
        accountId,
        provider: "nowpayments",
        sourceKey: `order:${orderId}:payment:${paymentId}`,
      });
      if (!settlement.settled) console.info(JSON.stringify({ message: "NOWPayments duplicate finished IPN", paymentId, orderId }));
    } else if (reversible) {
      await refundNowPaymentsCheckoutInDb(c.env.DB, {
        orderId,
        paymentId,
        sourceKey: `refund:${paymentId}`,
        refundedAt: now,
        entitlementSeconds: NOWPAYMENTS_ANNUAL_SECONDS,
      });
    }
    return c.json({ received: true });
  } catch (error) {
    console.error(JSON.stringify({ message: "NOWPayments webhook processing failed", paymentId, orderId, error: error instanceof Error ? error.message : String(error) }));
    return c.json({ error: "webhook processing failed" }, 500);
  }
});

app.post("/mailnice/webhook", async (c) => {
  const secret = (c.env as any).MAILNICE_WEBHOOK_SECRET as string | undefined;
  if (secret) {
    const header = c.req.header("x-mailnice-secret") || c.req.header("x-mailnice-webhook-secret") || c.req.header("authorization") || "";
    const provided = header.replace(/^Bearer\s+/i, "").trim();
    const urlSecret = new URL(c.req.url).searchParams.get("secret") || "";
    if (provided !== secret && urlSecret !== secret && header !== secret) return c.json({ error: "invalid webhook secret" }, 401);
  }
  let payload: any;
  try { payload = await c.req.json(); } catch { return c.json({ error: "invalid JSON" }, 400); }
  const rawEvent = String(payload.event || payload.type || payload.action || payload.message?.event || "").toLowerCase();
  const tag = String(payload.tag || payload.tenant_id || payload.tenantId || payload.message?.tag || payload.message?.tenant_id || payload.data?.tag || "").trim();
  const toEmail = String(payload.email || payload.recipient || payload.to || payload.message?.to || payload.data?.email || "").trim();
  const domain = String(payload.domain || payload.data?.domain || payload.message?.domain || "").trim().toLowerCase();
  let tenantId: number | null = null;
  if (/^\d+$/.test(tag)) tenantId = Number(tag);
  else if (tag) {
    const row = await c.env.DB.prepare("SELECT id FROM tenants WHERE public_id = ?").bind(tag).first<{ id: number }>();
    tenantId = row?.id ?? null;
  }
  if (!tenantId && toEmail) {
    const sub = await c.env.DB.prepare("SELECT tenant_id FROM subscribers WHERE email = ? LIMIT 1").bind(toEmail.toLowerCase()).first<{ tenant_id: number }>();
    tenantId = sub?.tenant_id ?? null;
  }
  if (!tenantId && domain) {
    const domRow = await c.env.DB.prepare("SELECT id FROM tenants WHERE custom_domain = ? OR slug = ? LIMIT 1").bind(domain, domain.replace(/\.blognice\.com$/i, "")).first<{ id: number }>();
    tenantId = domRow?.id ?? null;
    if (!tenantId) {
      try { recordCustomEvent(c.env as any, 0, { name: "domain_dns_error" as any, path: domain.slice(0,253), visitor: "", country: "", device: "", browser: "" }); } catch {}
    }
  }
  const exactMap: Record<string, string> = {
    messagesent: "email_delivered",
    messagedelayed: "email_delayed",
    messagedeliveryfailed: "email_delivery_failed",
    messageheld: "email_held",
    messagebounced: "email_bounced",
    messagelinkclicked: "email_clicked",
    messageloaded: "email_opened",
    domaindnserror: "domain_dns_error",
  };
  const map: Record<string, string> = {
    bounced: "email_bounced", bounce: "email_bounced",
    held: "email_held",
    failed: "email_delivery_failed", deliveryfailed: "email_delivery_failed",
    delayed: "email_delayed",
    complaint: "email_complained", spam: "email_complained", complained: "email_complained",
    opened: "email_opened", open: "email_opened", loaded: "email_opened",
    clicked: "email_clicked", click: "email_clicked",
    delivered: "email_delivered", sent: "email_delivered",
    dnserror: "domain_dns_error",
  };
  let eventName: string | null = exactMap[rawEvent] || null;
  if (!eventName) for (const [key, val] of Object.entries(map)) if (rawEvent.includes(key)) { eventName = val; break; }
  if (!eventName) return c.json({ ok: true, ignored: true });
  if (!tenantId) return c.json({ ok: true, ignored: true, reason: "tenant not resolved" });
  try { recordCustomEvent(c.env as any, tenantId, { name: eventName as any, path: "/", visitor: "", country: "", device: "", browser: "" }); } catch {}
  if (eventName === "email_bounced" || eventName === "email_complained" || eventName === "email_delivery_failed") {
    try {
      const email = toEmail.toLowerCase();
      if (email) await c.env.DB.prepare("INSERT OR IGNORE INTO email_suppressions (email, tenant_id, reason, created_at) VALUES (?, ?, ?, ?)").bind(email, tenantId, eventName, Math.floor(Date.now()/1000)).run().catch(()=>undefined);
    } catch {}
  }
  return c.json({ ok: true });
});

app.post("/stripe/webhook", async (c) => {
  const raw = await c.req.text();
  const signature = c.req.header("Stripe-Signature");
  const platformSignature = await verifyStripeSignature(raw, signature, c.env.STRIPE_WEBHOOK_SECRET);
  const connectSignature = platformSignature ? false : await verifyStripeSignature(raw, signature, c.env.STRIPE_CONNECT_WEBHOOK_SECRET);
  if (!platformSignature && !connectSignature) return c.json({ error: "invalid signature" }, 400);
  const event = JSON.parse(raw) as { id: string; type: string; created: number; data?: { object?: any } };
  const eventCreated = event.created || Math.floor(Date.now() / 1000);
  const inserted = await c.env.DB.prepare("INSERT OR IGNORE INTO stripe_events (id, type, created_at, processed_at, status) VALUES (?, ?, ?, 0, 'processing')").bind(event.id, event.type, eventCreated).run();
  if (!inserted.meta.changes) {
    const existing = await c.env.DB.prepare("SELECT status FROM stripe_events WHERE id = ?").bind(event.id).first<{ status: string }>();
    if (existing?.status === "processed") return c.json({ received: true, duplicate: true });
    await c.env.DB.prepare("UPDATE stripe_events SET status = 'processing', last_error = NULL WHERE id = ?").bind(event.id).run();
  }
  try {
  const object = event.data?.object || {};
  const entitlementEvent = event.type.startsWith("customer.subscription.") || event.type === "invoice.payment_failed";
  const invoiceSubscriptionId = typeof object.parent?.subscription_details?.subscription === "string"
    ? object.parent.subscription_details.subscription
    : typeof object.subscription === "string" ? object.subscription : null;
  let subscriptionObject = object;
  if (entitlementEvent && !event.type.endsWith(".deleted")) {
    const subscriptionId = event.type === "invoice.payment_failed" ? invoiceSubscriptionId : object.id;
    if (typeof subscriptionId === "string" && subscriptionId) subscriptionObject = await retrieveSubscription(c.env, subscriptionId);
  }
  const customerId = typeof (subscriptionObject.customer || object.customer) === "string" ? (subscriptionObject.customer || object.customer) : null;
  let accountId: number | null = Number(object.metadata?.account_id || 0) || null;
  if (!accountId && customerId) {
    const row = await c.env.DB.prepare("SELECT id FROM accounts WHERE stripe_customer_id = ?").bind(customerId).first<{ id: number }>();
    accountId = row?.id || null;
  }
  if (entitlementEvent && !accountId) throw new Error("Stripe billing event could not be mapped to a Blog Nice account yet.");
  if (event.type === "account.updated" && typeof object.id === "string") {
    const connectUpdate = await updateStripeConnectedAccountStatusInDb(c.env.DB, {
      connectedAccountId: object.id,
      detailsSubmitted: object.details_submitted === true,
      payoutsEnabled: object.payouts_enabled === true,
      transfersStatus: String(object.capabilities?.transfers || "inactive"),
      eventCreated,
      eventId: event.id,
    });
    if (connectUpdate.updated && c.env.EMAIL_QUEUE) c.executionCtx.waitUntil(relayAffiliateEmailOutboxInDb(c.env.DB, c.env.EMAIL_QUEUE));
    const affiliate = await c.env.DB.prepare(
      "SELECT account_id FROM affiliate_profiles WHERE stripe_connected_account_id = ?",
    ).bind(object.id).first<{ account_id: number }>();
    accountId = affiliate?.account_id || accountId;
    if (accountId) await c.env.DB.prepare("UPDATE stripe_events SET account_id = ? WHERE id = ?").bind(accountId, event.id).run();
  }
  if (event.type === "checkout.session.completed" && object.metadata?.type === "domain_purchase") {
    const meta: any = object.metadata || {};
    const domain = String(meta.domain || "").toLowerCase().trim();
    const tenantId = Number(meta.tenant_id || 0);
    const duration = Math.max(1, Math.min(10, parseInt(String(meta.duration || "1"), 10) || 1));
    const privacy = String(meta.privacy || "full").toLowerCase() as "off" | "partial" | "full";
    const accId = Number(meta.account_id || accountId || 0) || accountId;
    if (!domain || !tenantId || !accId) throw new Error("Domain purchase metadata missing domain/tenant/account.");
    const paymentStatus = String(object.payment_status || object.status || "");
    if (paymentStatus !== "paid" && paymentStatus !== "complete" && object.status !== "complete") {
      await c.env.DB.prepare("UPDATE stripe_events SET account_id = ?, status = 'processed', processed_at = ?, last_error = NULL WHERE id = ?").bind(accId, Math.floor(Date.now() / 1000), event.id).run();
      return c.json({ received: true, domain_pending: true });
    }
    const existing = await c.env.DB.prepare("SELECT hostname FROM domains WHERE hostname = ? AND tenant_id = ?").bind(domain, tenantId).first();
    if (existing) {
      await c.env.DB.prepare("UPDATE stripe_events SET account_id = ?, status = 'processed', processed_at = ?, last_error = NULL WHERE id = ?").bind(accId, Math.floor(Date.now() / 1000), event.id).run();
      return c.json({ received: true, duplicate_domain: true });
    }
    const contactRes = await createContact(c.env as any, {
      organization: meta.contact_org || undefined,
      name: String(meta.contact_name || ""),
      email: String(meta.contact_email || ""),
      phone_number: String(meta.contact_phone || ""),
      phone_cc: String(meta.contact_phone_cc || ""),
      address1: String(meta.contact_address1 || ""),
      city: String(meta.contact_city || ""),
      state: String(meta.contact_state || "") || undefined,
      zip: String(meta.contact_zip || ""),
      country: String(meta.contact_country || ""),
    });
    if (!contactRes.ok) throw new Error(sanitizeDynadotErrorMessage(contactRes.error || "Contact creation failed for domain purchase."));
    const contactId = (contactRes.data as any)?.contact_id;
    if (!contactId) throw new Error("Contact creation returned no ID for domain purchase.");
    const reg = await dynadotRegisterDomain(c.env as any, domain, {
      duration,
      registrant_contact_id: contactId,
      admin_contact_id: contactId,
      tech_contact_id: contactId,
      billing_contact_id: contactId,
      privacy,
      currency: "USD",
    });
    if (!reg.ok) throw new Error(sanitizeDynadotErrorMessage(reg.error || "Registration failed for domain purchase."));
    let cfHostnameId: string | null = null;
    try {
      const created = await createCustomHostname(c.env as any, domain);
      if (created.ok) cfHostnameId = (created as any).result?.id ?? null;
      else {
        const found = await findCustomHostname(c.env as any, domain);
        const hit = Array.isArray((found as any).result) ? (found as any).result[0] : null;
        if (hit) cfHostnameId = hit.id ?? null;
      }
    } catch {}
    try {
      await setDnsRecords(c.env as any, domain, {
        dns_main_list: [{ host: "@", type: "CNAME", value: c.env.CNAME_TARGET, ttl: 3600 }],
        ttl: 3600,
        add_dns_to_current_setting: false,
      });
    } catch {}
    const now = Math.floor(Date.now() / 1000);
    await c.env.DB.prepare(
      `INSERT INTO domains (hostname, tenant_id, cf_hostname_id, status, created_at) VALUES (?, ?, ?, 'pending', ?) ON CONFLICT(hostname) DO UPDATE SET tenant_id=excluded.tenant_id, cf_hostname_id=excluded.cf_hostname_id`
    )
      .bind(domain, tenantId, cfHostnameId, now)
      .run();
    try {
      const auditTenant = tenantId;
      const auditActor = accId;
      if (auditTenant && auditActor) {
        const isPaid = await (async () => {
          try {
            const owner = await c.env.DB.prepare(`SELECT COALESCE(a.billing_status,'inactive') AS billing_status FROM memberships m JOIN accounts a ON a.id=m.account_id WHERE m.tenant_id=? AND m.role='owner' LIMIT 1`).bind(auditTenant).first<any>();
            return owner && (owner.billing_status === 'active' || owner.billing_status === 'trialing');
          } catch { return false; }
        })();
        if (isPaid) {
          const { recordAuditEvent } = await import("./metrics");
          await recordAuditEvent(c.env as any, auditTenant, { action: "custom_domain_added", target: domain + " (purchased via Dynadot + Stripe)", actor: String(auditActor) });
        }
      }
    } catch {}
    await c.env.DB.prepare("UPDATE stripe_events SET account_id = ?, status = 'processed', processed_at = ?, last_error = NULL WHERE id = ?").bind(accId, Math.floor(Date.now() / 1000), event.id).run();
    return c.json({ received: true, domain_provisioned: true });
  }
  if (event.type === "invoice.payment_failed" && accountId) {
    const accountBilling = await c.env.DB.prepare("SELECT stripe_subscription_id FROM accounts WHERE id = ?").bind(accountId).first<{ stripe_subscription_id: string | null }>();
    if (!invoiceSubscriptionId || !accountBilling?.stripe_subscription_id || invoiceSubscriptionId !== accountBilling.stripe_subscription_id) {
      await c.env.DB.prepare("UPDATE stripe_events SET account_id = ? WHERE id = ?").bind(accountId, event.id).run();
      // This invoice is unrelated to Blog Nice's subscription; acknowledge it.
      subscriptionObject = null;
    }
  }
  if (event.type === "checkout.session.completed" && accountId && customerId && typeof object.subscription === "string") {
    const incomingSubscription = await retrieveSubscription(c.env, object.subscription);
    const currentBilling = await c.env.DB.prepare("SELECT stripe_subscription_id, billing_subscription_created_at FROM accounts WHERE id = ?")
      .bind(accountId).first<{ stripe_subscription_id: string | null; billing_subscription_created_at: number | null }>();
    let currentCreated = currentBilling?.billing_subscription_created_at || null;
    if (currentBilling?.stripe_subscription_id && currentBilling.stripe_subscription_id !== incomingSubscription.id && !currentCreated) {
      // Backfill the comparison value for subscriptions created before this
      // column existed. If Stripe cannot provide it, fail and let Stripe retry;
      // guessing could allow an old Checkout session to replace a newer one.
      const currentSubscription = await retrieveSubscription(c.env, currentBilling.stripe_subscription_id);
      currentCreated = currentSubscription.created || null;
      if (!currentCreated) throw new Error("Stripe did not return the current subscription creation time.");
    }
    if (!incomingSubscription.created) throw new Error("Stripe did not return the completed subscription creation time.");
    const checkoutDecision = checkoutSubscriptionDecision({
      currentId: currentBilling?.stripe_subscription_id,
      currentCreated,
      incomingId: incomingSubscription.id,
      incomingCreated: incomingSubscription.created,
    });
    if (checkoutDecision !== "ignore") {
      const checkoutStatus = String(incomingSubscription.status || "inactive");
      const checkoutPeriodEnd = incomingSubscription.current_period_end || incomingSubscription.items?.data?.[0]?.current_period_end || null;
      if (checkoutDecision === "adopt") {
        // A new subscription starts a new event-ordering stream. Reset the
        // webhook cursor even if an old subscription produced a later event.
        await c.env.DB.prepare("UPDATE accounts SET stripe_customer_id = ?, stripe_subscription_id = ?, billing_subscription_created_at = ?, billing_status = ?, billing_price_id = ?, billing_period_end = ?, billing_cancel_at_period_end = ?, billing_updated_at = ?, billing_event_created_at = ?, billing_event_id = ? WHERE id = ?")
          .bind(customerId, incomingSubscription.id, incomingSubscription.created, checkoutStatus, incomingSubscription.items?.data?.[0]?.price?.id || null, checkoutPeriodEnd, incomingSubscription.cancel_at_period_end ? 1 : 0, Math.floor(Date.now() / 1000), eventCreated, event.id, accountId).run();
      } else {
        // Reprocessing Checkout for the same subscription refreshes live state
        // without moving its event-ordering cursor backwards.
        await c.env.DB.prepare("UPDATE accounts SET stripe_customer_id = ?, billing_subscription_created_at = COALESCE(billing_subscription_created_at, ?), billing_status = ?, billing_price_id = ?, billing_period_end = ?, billing_cancel_at_period_end = ?, billing_updated_at = ?, billing_event_created_at = CASE WHEN COALESCE(billing_event_created_at, 0) < ? THEN ? ELSE billing_event_created_at END, billing_event_id = CASE WHEN COALESCE(billing_event_created_at, 0) < ? THEN ? ELSE billing_event_id END WHERE id = ?")
          .bind(customerId, incomingSubscription.created, checkoutStatus, incomingSubscription.items?.data?.[0]?.price?.id || null, checkoutPeriodEnd, incomingSubscription.cancel_at_period_end ? 1 : 0, Math.floor(Date.now() / 1000), eventCreated, eventCreated, eventCreated, event.id, accountId).run();
      }
    }
    await c.env.DB.prepare("UPDATE stripe_events SET account_id = ? WHERE id = ?").bind(accountId, event.id).run();
  }
  if (event.type === "invoice.paid" && accountId && invoiceSubscriptionId) {
    const invoiceLines = Array.isArray(object.lines?.data) ? object.lines.data : [];
    for (const line of invoiceLines) {
      const proration = Boolean(
        line.proration
        || line.parent?.subscription_item_details?.proration,
      );
      if (proration) continue;
      const checkoutId = String(
        line.metadata?.affiliate_checkout_id
        || object.parent?.subscription_details?.metadata?.affiliate_checkout_id
        || "",
      );
      const priceId = String(line.pricing?.price_details?.price || line.price?.id || "");
      if (!checkoutId || !priceId || !line.id) continue;
      if (String(line.currency || object.currency || "").toLowerCase() !== "usd") continue;
      const pretaxCredits = Array.isArray(line.pretax_credit_amounts)
        ? line.pretax_credit_amounts.reduce((sum: number, credit: any) => sum + Number(credit.amount || 0), 0)
        : Array.isArray(line.discount_amounts)
          ? line.discount_amounts.reduce((sum: number, discount: any) => sum + Number(discount.amount || 0), 0)
          : 0;
      const subtotalMinor = Number(line.subtotal ?? line.amount_excluding_tax ?? line.amount ?? 0);
      const eligibleRevenueMinor = Math.max(0, subtotalMinor - pretaxCredits);
      if (!eligibleRevenueMinor) continue;
      const serviceStartAt = Number(line.period?.start || 0);
      const serviceEndAt = Number(line.period?.end || 0);
      if (!Number.isSafeInteger(serviceStartAt) || !Number.isSafeInteger(serviceEndAt)
        || serviceEndAt <= serviceStartAt) continue;
      const settlement = await settleStripeInvoiceInDb(c.env.DB, {
        checkoutId,
        invoiceId: String(object.id),
        paymentId: String(object.payment_intent || object.id),
        subscriptionId: invoiceSubscriptionId,
        lineId: String(line.id),
        priceId,
        currency: "usd",
        discountedAmountExcludingTaxMinor: eligibleRevenueMinor,
        processingFeeMinor: 0,
        serviceStartAt,
        serviceEndAt,
        paidAt: Number(object.status_transitions?.paid_at || eventCreated),
        maturationSeconds: 60 * 24 * 60 * 60,
      });
      if (settlement.created) await recordAffiliateConversion(c, accountId, "stripe");
      await recordFunnelExperimentConversionInDb(c.env.DB, {
        accountId,
        provider: "stripe",
        sourceKey: `invoice:${String(object.id)}:line:${String(line.id)}`,
      });
    }
    await c.env.DB.prepare("UPDATE stripe_events SET account_id = ? WHERE id = ?").bind(accountId, event.id).run();
  }
  if (event.type === "charge.refunded") {
    const paymentId = typeof object.payment_intent === "string" ? object.payment_intent : "";
    const originalChargeMinor = Number(object.amount || 0);
    const refunds = Array.isArray(object.refunds?.data) ? object.refunds.data : [];
    if (paymentId && originalChargeMinor > 0) {
      for (const refund of refunds) {
        if (!refund?.id || Number(refund.amount || 0) <= 0) continue;
        await recordPendingStripeFinancialEventInDb(c.env.DB, {
          kind: "refund", sourceKey: `refund:${String(refund.id)}`, paymentId,
          amountMinor: Number(refund.amount), originalAmountMinor: originalChargeMinor,
          occurredAt: Number(refund.created || eventCreated),
        });
      }
    }
    if (accountId) {
      await c.env.DB.prepare("UPDATE stripe_events SET account_id = ? WHERE id = ?").bind(accountId, event.id).run();
    }
  }
  if ((event.type === "credit_note.created" || event.type === "credit_note.updated")
    && object.status !== "void" && !object.refund) {
    const invoiceId = typeof object.invoice === "string" ? object.invoice : String(object.invoice?.id || "");
    const creditNoteId = String(object.id || "");
    const lines = Array.isArray(object.lines?.data) ? object.lines.data : [];
    for (const line of lines) {
      const invoiceLineId = typeof line.invoice_line_item === "string"
        ? line.invoice_line_item
        : String(line.invoice_line_item?.id || "");
      const creditedEligibleRevenueMinor = Number(line.amount_excluding_tax ?? line.amount ?? 0);
      if (!invoiceId || !creditNoteId || !invoiceLineId || creditedEligibleRevenueMinor <= 0) continue;
      await recordPendingStripeFinancialEventInDb(c.env.DB, {
        kind: "credit_note", sourceKey: `credit_note:${creditNoteId}:line:${invoiceLineId}`,
        invoiceId, invoiceLineId, amountMinor: creditedEligibleRevenueMinor,
        occurredAt: Number(object.created || eventCreated),
      });
    }
  }
  if (event.type === "charge.dispute.created") {
    const paymentId = typeof object.payment_intent === "string" ? object.payment_intent : "";
    const disputeId = String(object.id || "");
    if (paymentId && disputeId) {
      await recordPendingStripeFinancialEventInDb(c.env.DB, {
        kind: "dispute_open", sourceKey: `dispute:${disputeId}:opened`,
        paymentId, disputeId, occurredAt: Number(object.created || eventCreated),
      });
    }
  }
  if (event.type === "charge.dispute.closed") {
    const disputeId = String(object.id || "");
    const outcome = object.status === "won" || object.status === "warning_closed"
      ? "won"
      : object.status === "lost" ? "lost" : null;
    if (disputeId && outcome) {
      await recordPendingStripeFinancialEventInDb(c.env.DB, {
        kind: "dispute_close", sourceKey: `dispute:${disputeId}:${outcome}`,
        disputeId, outcome, occurredAt: Number(object.created || eventCreated),
      });
    }
  }
  if (event.type.startsWith("customer.subscription.") && accountId && subscriptionObject) {
    const currentBilling = await c.env.DB.prepare("SELECT stripe_subscription_id FROM accounts WHERE id = ?")
      .bind(accountId).first<{ stripe_subscription_id: string | null }>();
    const incomingSubscriptionId = String(subscriptionObject.id || object.id || "");
    if (!subscriptionEventMatchesCurrent(currentBilling?.stripe_subscription_id, incomingSubscriptionId)) {
      // A delayed event from an older Stripe subscription must never replace the
      // account's current subscription or revoke its entitlement.
      await c.env.DB.prepare("UPDATE stripe_events SET account_id = ? WHERE id = ?").bind(accountId, event.id).run();
      subscriptionObject = null;
    }
  }
  if (event.type.startsWith("customer.subscription.") && accountId && subscriptionObject) {
    const status = event.type.endsWith(".deleted") ? "canceled" : String(subscriptionObject.status || "inactive");
    const periodEnd = subscriptionObject.current_period_end || subscriptionObject.items?.data?.[0]?.current_period_end || null;
    const subscriptionUpdate = await c.env.DB.prepare("UPDATE accounts SET stripe_customer_id = COALESCE(?, stripe_customer_id), stripe_subscription_id = ?, billing_subscription_created_at = COALESCE(?, billing_subscription_created_at), billing_status = ?, billing_price_id = ?, billing_period_end = ?, billing_cancel_at_period_end = ?, billing_updated_at = ?, billing_event_created_at = ?, billing_event_id = ? WHERE id = ? AND (COALESCE(billing_event_created_at, 0) < ? OR (COALESCE(billing_event_created_at, 0) = ? AND COALESCE(billing_event_id, '') < ?))")
      .bind(customerId, subscriptionObject.id || object.id || null, subscriptionObject.created || null, status, subscriptionObject.items?.data?.[0]?.price?.id || null, periodEnd, subscriptionObject.cancel_at_period_end ? 1 : 0, Math.floor(Date.now() / 1000), eventCreated, event.id, accountId, eventCreated, eventCreated, event.id).run();
    await c.env.DB.prepare("UPDATE stripe_events SET account_id = ? WHERE id = ?").bind(accountId, event.id).run();
    if (event.type === "customer.subscription.created" && ["active", "trialing"].includes(status) && c.env.EMAIL_QUEUE && emailEnabled(c.env)) {
      const account = await c.env.DB.prepare("SELECT email, stripe_subscription_id, billing_status FROM accounts WHERE id = ?").bind(accountId).first<{ email: string; stripe_subscription_id: string | null; billing_status: string }>();
      if (account?.email && object.id && account.stripe_subscription_id === String(object.id) && ["active", "trialing"].includes(account.billing_status)) {
        const idempotencyKey = `subscription-welcome:${accountId}:${String(object.id)}`;
        const welcome = await c.env.DB.prepare(
          `INSERT OR IGNORE INTO email_delivery_log (idempotency_key, status, recipient, kind, created_at)
           VALUES (?, 'pending', ?, 'subscription-welcome', ?)`
        ).bind(idempotencyKey, account.email, Math.floor(Date.now() / 1000)).run();
        let shouldQueue = Boolean(welcome.meta.changes);
        if (!welcome.meta.changes) {
          const existing = await c.env.DB.prepare("SELECT status, created_at FROM email_delivery_log WHERE idempotency_key = ?").bind(idempotencyKey).first<{ status: string; created_at: number }>();
          if (existing?.status === "sent" || existing?.status === "queued") shouldQueue = false;
          else if (existing?.status === "pending" && Math.floor(Date.now() / 1000) - Number(existing.created_at || 0) < 300) {
            throw new Error("Subscription activation email is already being queued.");
          } else {
            const reclaimed = await c.env.DB.prepare("UPDATE email_delivery_log SET status = 'pending', created_at = ? WHERE idempotency_key = ? AND status = 'pending' AND created_at < ?")
              .bind(Math.floor(Date.now() / 1000), idempotencyKey, Math.floor(Date.now() / 1000) - 300).run();
            if (reclaimed.meta.changes !== 1) throw new Error("Subscription activation email claim could not be recovered.");
            shouldQueue = true;
          }
        }
        if (shouldQueue) {
          const billingUrl = `https://www.${c.env.ROOT_DOMAIN}/admin/billing`;
          try {
            await c.env.EMAIL_QUEUE.send({
              kind: "email-delivery",
              emailKind: "subscription-active",
              idempotencyKey,
              to: account.email,
              ...subscriptionActiveEmail({ billingUrl, plan: subscriptionObject.items?.data?.[0]?.price?.id === c.env.STRIPE_YEARLY_PRICE_ID ? "yearly" : subscriptionObject.items?.data?.[0]?.price?.id === c.env.STRIPE_MONTHLY_PRICE_ID ? "monthly" : undefined }),
            } satisfies EmailJobMessage);
            await c.env.DB.prepare("UPDATE email_delivery_log SET status = 'queued' WHERE idempotency_key = ? AND status = 'pending'").bind(idempotencyKey).run();
          } catch (error) {
            await c.env.DB.prepare("DELETE FROM email_delivery_log WHERE idempotency_key = ? AND status = 'pending'").bind(idempotencyKey).run();
            throw error;
          }
        }
      }
    }
  }
  if (event.type === "invoice.payment_failed" && accountId && subscriptionObject) {
    // Preserve the authoritative Stripe status. In particular, an initial
    // failed payment can be `incomplete`/`incomplete_expired`/`paused`; mapping
    // those to `past_due` would incorrectly grant Pro access.
    const stripeStatus = String(subscriptionObject.status || "inactive");
    const reconciledStatus = ["active", "trialing", "past_due", "canceled", "unpaid", "incomplete", "incomplete_expired", "paused"].includes(stripeStatus)
      ? stripeStatus
      : "inactive";
    await c.env.DB.prepare("UPDATE accounts SET billing_status = ?, billing_updated_at = ?, billing_event_created_at = ?, billing_event_id = ? WHERE id = ? AND (COALESCE(billing_event_created_at, 0) < ? OR (COALESCE(billing_event_created_at, 0) = ? AND COALESCE(billing_event_id, '') < ?))").bind(reconciledStatus, Math.floor(Date.now() / 1000), eventCreated, event.id, accountId, eventCreated, eventCreated, event.id).run();
    await c.env.DB.prepare("UPDATE stripe_events SET account_id = ? WHERE id = ?").bind(accountId, event.id).run();
  }
    await c.env.DB.prepare("UPDATE stripe_events SET status = 'processed', processed_at = ?, last_error = NULL WHERE id = ?").bind(Math.floor(Date.now() / 1000), event.id).run();
    return c.json({ received: true });
  } catch (error) {
    const detail = error instanceof Error ? error.message.slice(0, 500) : String(error).slice(0, 500);
    await c.env.DB.prepare("UPDATE stripe_events SET status = 'failed', last_error = ? WHERE id = ?").bind(detail, event.id).run().catch(() => undefined);
    console.error(JSON.stringify({ message: "Stripe webhook processing failed", eventId: event.id, error: detail }));
    return c.json({ error: "webhook processing failed" }, 500);
  }
});

app.post("/manage-subscriptions/:token", async (c) => {
  const token = c.req.param("token");
  const identity = await c.env.DB.prepare("SELECT email FROM subscription_manage_tokens WHERE token = ?")
    .bind(token).first<{ email: string }>();
  if (!identity) return c.text("Invalid subscription management link", 404);
  const form = await c.req.formData();
  const selected = new Set(form.getAll("subscription").map(String));
  const subscriptions = await c.env.DB.prepare("SELECT id FROM subscribers WHERE email = ?")
    .bind(identity.email).all<{ id: number }>();
  const remove = subscriptions.results.filter((row) => !selected.has(String(row.id)));
  if (remove.length) await c.env.DB.batch(remove.map((row) => c.env.DB.prepare("DELETE FROM subscribers WHERE id = ? AND email = ?").bind(row.id, identity.email)));
  const remaining = await c.env.DB.prepare("SELECT s.id, t.title, t.slug, t.custom_domain FROM subscribers s JOIN tenants t ON t.id = s.tenant_id WHERE s.email = ? AND s.confirmed_at IS NOT NULL ORDER BY t.title")
    .bind(identity.email).all<{ id: number; title: string; slug: string; custom_domain?: string | null }>();
  return c.html(subscriptionManagePage(identity.email, remaining.results, token, "Your subscription preferences have been saved."));
});

